const e={lerninhalte:{"grundlagen-des-wirtschaftens":{schritte:[{titel:"Needs",blocks:[{type:"text",text:"Everything in the economy starts with one question: What am I missing right now?"},{type:"begriff",term:"Need",erklaerung:"You notice that something is missing and you want to change that.",beispiel:"You are thirsty → you want something to drink."},{type:"kette",glieder:[{titel:"Feeling of lack (need)",wert:"Thirst"},{titel:"Satisfying the need",wert:"drinking"},{titel:"Means to do it",wert:"Water"}]},{type:"text",text:"Maslow's hierarchy of needs ranks needs by how urgent they are. The lowest level is fulfilled first, then the next one."},{type:"pyramide",stufen:[{name:"Self-actualisation",beispiel:"Developing your talents, dream job"},{name:"Esteem",beispiel:"Praise, success, career"},{name:"Social needs",beispiel:"Friends, family, relationships"},{name:"Safety",beispiel:"Health, secure job, money"},{name:"Basic needs",beispiel:"Food, drink, sleep"}]},{type:"begriff",term:"Basic needs (existential needs)",erklaerung:"You need them to survive. They are also called primary needs.",beispiel:"Food, drink, clothing, housing"},{type:"begriff",term:"Cultural needs",erklaerung:"Make life pleasant and stimulate the mind. Not essential for survival.",beispiel:"Education, holidays, sport, cinema"},{type:"begriff",term:"Luxury needs",erklaerung:"Expensive things that show you can afford a lot (social status).",beispiel:"Sports car, villa, trip around the world"},{type:"merke",text:"Cultural and luxury needs together are called secondary needs."}]},{titel:"Goods",blocks:[{type:"begriff",term:"Goods",erklaerung:"Everything we use to satisfy needs. Another word: products."},{type:"text",text:"Goods can be classified in three ways:"},{type:"vergleich",frage:"1. Does it cost something?",links:{titel:"Free goods",punkte:["Unlimited in nature","Usually free of charge","e.g. air, sunlight"]},rechts:{titel:"Economic goods",punkte:["Are scarce","Cost money – the scarcer, the more expensive","e.g. cocoa, crude oil"]}},{type:"vergleich",frage:"2. Can you touch it?",links:{titel:"Physical goods (tangible)",punkte:["Can be touched","Can be stored and transported","e.g. car, furniture, clothing"]},rechts:{titel:"Services (intangible)",punkte:["Cannot be touched","Cannot be stored","e.g. haircut, visit to the doctor"]}},{type:"begriff",term:"Object-related / person-related service",erklaerung:"Object-related: done to a thing. Person-related: done to a person.",beispiel:"Car repair (thing) – medical check-up (person)"},{type:"vergleich",frage:"3. What is it used for?",links:{titel:"Consumer goods",punkte:["Are used up/used by yourself","e.g. food, cosmetics, a car for private use"]},rechts:{titel:"Capital goods",punkte:["A company uses them to make other goods","e.g. machine, delivery van, office building"]}},{type:"merke",text:"Economic goods are divided into physical goods and services. Whether something is a consumer or capital good depends on WHO uses it FOR WHAT."},{type:"entscheidung",titel:"Goods check: Which type of good is it?",schritte:[{frage:"Is it scarce and does it cost money?",links:{antwort:"No",ergebnis:"Free good",beispiel:"Air, sunlight"},rechts:{antwort:"Yes",weiter:"Economic good"}},{frage:"Can you touch it?",links:{antwort:"No",ergebnis:"Service",beispiel:"Haircut, visit to the doctor"},rechts:{antwort:"Yes",weiter:"Physical good"}},{frage:"What is it used for?",links:{antwort:"To consume",ergebnis:"Consumer good",beispiel:"Food, clothing"},rechts:{antwort:"To produce",ergebnis:"Capital good",beispiel:"Machine, delivery van"}}]}]},{titel:"Economic activity",blocks:[{type:"text",text:"We want a lot, but only have limited money and time. So we have to divide things up wisely."},{type:"begriff",term:"Scarcity",erklaerung:"Our means (money, time, raw materials) are never enough for all our wishes."},{type:"begriff",term:"Economic activity",erklaerung:"Acting in a planned and sensible (rational) way so that scarcity becomes smaller.",beispiel:"You budget your pocket money so that it covers the most important things."},{type:"begriff",term:"Sustainability",erklaerung:"Doing business in a way that future generations will still have enough resources."}]},{titel:"Minimum & maximum principle",blocks:[{type:"begriff",term:"Economic principle",erklaerung:"Finding the best ratio between needs and scarce means. Works in 2 ways:"},{type:"prinzip",minimal:"I want a basketball → I look for the cheapest one.",maximal:"I have €30 → I buy as many snacks as possible."},{type:"merke",text:"Trick: What is fixed? The GOAL is fixed → minimum principle. The MONEY/INPUT is fixed → maximum principle."}]},{titel:"Economic participants",blocks:[{type:"begriff",term:"Economic participants",erklaerung:"All people and institutions that take part in the economy. Including you!"},{type:"begriff",term:"Companies",erklaerung:"Produce goods or offer services.",beispiel:"Bakery, hairdresser, OMV"},{type:"begriff",term:"Households",erklaerung:"One person or a family. Earn money by working, use it to buy things or save (= consumers)."},{type:"begriff",term:"State",erklaerung:"Makes laws, collects taxes and spends them e.g. on schools, roads and family allowance."},{type:"begriff",term:"Banks",erklaerung:"Accept savings and lend money (loans). Interest is paid for this."},{type:"begriff",term:"Taxes",erklaerung:"Money that you must pay to the state by law."},{type:"begriff",term:"Subsidies",erklaerung:"Money from the state to support companies for a specific purpose.",beispiel:"Funding for research or solar panels"}]},{titel:"Circular flow of the economy",blocks:[{type:"begriff",term:"Circular flow of the economy",erklaerung:"Shows how all economic participants are connected – based on the principle of “give and take”."},{type:"text",text:"Start with “Simple” (core relationship companies ↔ households), then “Extended” adds the banks and “Complete” adds the state."},{type:"kreislaufDiagramm"},{type:"merke",text:"Complete circular flow = 4 participants: companies, households, banks, state."}]}],zusammenfassung:[{titel:"Needs",punkte:["Need = feeling of lack + wish to remove it","Maslow's pyramid (bottom → top): basic needs → safety → social → esteem → self-actualisation","Primary needs = basic needs (essential for survival)","Secondary needs = cultural needs (education, holidays) + luxury needs (status)"]},{titel:"Goods",punkte:["Goods = means of satisfying needs","Free goods (unlimited, free) ↔ economic goods (scarce, cost money)","Economic goods = physical goods (tangible) + services (intangible, cannot be stored)","Services: object-related (car repair) or person-related (doctor)","Consumer goods (final consumption) ↔ capital goods (for producing other goods)"]},{titel:"Economic activity",punkte:["Economic activity = planned, rational action to reduce scarcity","Sustainability = using resources so that future generations have enough"]},{titel:"Economic principle",punkte:["Minimum principle: goal fixed → as little input as possible","Maximum principle: input fixed → as large a result as possible"]},{titel:"Economic participants & circular flow",punkte:["Companies: produce goods/services","Households: provide labour, receive income, buy goods, save","State: laws, taxes, subsidies, benefits","Banks: accept savings/investments, grant loans, interest","Core relationship: companies ↔ households (labour ↔ income, goods ↔ purchase price)","Simple: C + H · Extended: + banks · Complete: + state"]}]},"der-markt":{schritte:[{titel:"Division of labour",blocks:[{type:"text",text:"In the past everyone did everything themselves. Today work is divided up – that is faster and better."},{type:"begriff",term:"Division of labour",erklaerung:"A big task is split into many small steps that different people or companies take over."},{type:"begriff",term:"Specialisation",erklaerung:"A company or person only does what they are especially good at (know-how).",beispiel:"Farmer harvests tomatoes → factory makes ketchup → supermarket sells it."},{type:"tabelle",spalten:["Type","Who shares the work?","Example"],zeilen:[["Within the company","Departments/employees in ONE company","Purchasing, accounting, sales"],["National","Different companies in one country","Dairy, farmer, supermarket"],["International","Different countries","Bananas from Ecuador, phone from China"]]}]},{titel:"Economic sectors",blocks:[{type:"text",text:"National division of labour can be vertical or horizontal."},{type:"begriff",term:"Vertical division of labour",erklaerung:"Companies at DIFFERENT stages of production work one after another on the same product."},{type:"ablauf",titel:"Example jeans (vertical)",schritte:[{titel:"Primary production",text:"Growing cotton"},{titel:"Service",text:"Wholesale, transport"},{titel:"Production",text:"Spinning mill, weaving mill, clothing factory"},{titel:"Service",text:"Transport, retail → customer"}]},{type:"begriff",term:"Horizontal division of labour",erklaerung:"Companies at the SAME stage specialise in different products.",beispiel:"One company makes bridal wear, another sportswear."},{type:"tabelle",spalten:["Sector","What happens?","Example"],zeilen:[["Primary (primary production)","Extracting raw materials","Agriculture, forestry, oil production"],["Secondary (production)","Processing raw materials","Sawmill, joinery"],["Tertiary (services)","Providing goods, services","Furniture store, hairdresser"]]},{type:"merke",text:"Today people also talk about a quaternary sector (information) and a quinary sector (waste disposal)."}]},{titel:"Market, supply & demand",blocks:[{type:"begriff",term:"Market",erklaerung:"Any place where goods are exchanged for money. Can be physical (supermarket) or online."},{type:"vergleich",links:{titel:"Supplier (seller)",punkte:["Offers goods = supply","Receives money for them"]},rechts:{titel:"Buyer (customer)",punkte:["Asks for goods = demand","Pays money for them"]}}]},{titel:"Types of markets",blocks:[{type:"text",text:"Markets are classified by WHAT is traded and by HOW MANY take part."},{type:"tabelle",spalten:["Market","What is traded?"],zeilen:[["Consumer goods market","Physical goods for end consumers (clothing)"],["Capital goods market","Physical goods for companies (machines)"],["Services market","personal (hairdresser) or object-related (repair)"],["Labour market","Labour"],["Capital market","Money (loans, investments)"],["Property market","Land and buildings"]]},{type:"begriff",term:"Factor markets",erklaerung:"Markets for factors of production: labour, land and capital (labour, property, capital market)."},{type:"tabelle",spalten:["Market form","Suppliers/buyers","Example"],zeilen:[["Polypoly","many","Clothing"],["Oligopoly","few","Mobile phone providers"],["Monopoly","one","Gambling (state), ÖBB as a buyer of Railjet trains"]]},{type:"merke",text:"Poly = many, oligo = few, mono = one. The fewer participants, the more market power – prices can be artificially high."}]},{titel:"Price formation",blocks:[{type:"begriff",term:"Price",erklaerung:"Money you have to pay for a good. It is mainly determined by supply and demand."},{type:"text",text:"The seller wants as high a price as possible, the buyer as low as possible. The market price is the compromise."},{type:"begriff",term:"Law of demand",erklaerung:"Price rises → demand falls. Price falls → demand rises."},{type:"begriff",term:"Law of supply",erklaerung:"Price rises → supply rises. Price falls → supply falls."},{type:"marktdiagramm"},{type:"begriff",term:"Equilibrium price",erklaerung:"The price where the curves intersect: quantity supplied = quantity demanded (market equilibrium)."},{type:"vergleich",frage:"What else influences the price?",links:{titel:"On the seller's side",punkte:["Production costs","Profit margin","Competitors' prices","Technology","Taxes"]},rechts:{titel:"On the buyer's side",punkte:["Income","Usefulness of the good","Tax level","Urgent need (medicines)"]}}]},{titel:"Economic systems",blocks:[{type:"begriff",term:"Economic system",erklaerung:"The rules by which the economy works in a country. Difference: How much does the state decide?"},{type:"tabelle",spalten:["","Free market economy","(Eco-)social market economy","Planned economy"],zeilen:[["Who plans?","Everyone themselves","Everyone themselves, the state steers too","The state (central plan)"],["Price","Supply & demand","Supply & demand","The state decides"],["State","Only sets the framework","Intervenes strongly (social, ecological)","Decides everything"],["Disadvantage","Gap between rich and poor","–","Too many/too few goods"],["Example","–","Austria, Germany","North Korea, partly Cuba"]]},{type:"begriff",term:"Free market economy – features",erklaerung:"Free planning, state only sets the framework, free choice of job and workplace, private ownership of factors of production."},{type:"begriff",term:"(Eco-)social market economy – features",erklaerung:"Social steering (family allowance), controlled competition (consumer protection), ecological steering (environmental laws, subsidies), state intervention (public contracts, help in crises)."},{type:"begriff",term:"Public services",erklaerung:"Goods and services that the state provides for everyone.",beispiel:"Free school books, public transport"}]}],zusammenfassung:[{titel:"Division of labour",punkte:["Division of labour = splitting work into small steps; basis of specialisation","Specialisation = only producing certain goods because you have the know-how","Within the company (1 company) · national (companies in 1 country) · international (countries)","Vertical = different stages of production · horizontal = same stage, different products","Sectors: primary (primary production) · secondary (production) · tertiary (services)"]},{titel:"Market",punkte:["Market = place where supply (sellers) and demand (buyers) meet","By what is traded: physical goods, services, factor markets (labour, capital, property)","By participants: polypoly (many) · oligopoly (few) · monopoly (one)"]},{titel:"Price formation",punkte:["Law of demand: price ↑ → demand ↓","Law of supply: price ↑ → supply ↑","Intersection of the curves = equilibrium price / equilibrium quantity (market equilibrium)","Other factors: production costs, competition, taxes, income, usefulness"]},{titel:"Economic systems",punkte:["Free market economy: state only sets the framework, price set by supply & demand","(Eco-)social market economy: like the free one, but the state intervenes socially & ecologically (Austria)","Planned economy: state plans centrally (central plan), sets prices, no competition"]}]},"unternehmen-und-umfeld":{schritte:[{titel:"Enterprise, establishment, company name",blocks:[{type:"text",text:"These three words are often mixed up in everyday life. In business studies they mean different things:"},{type:"tabelle",spalten:["Term","Meaning","Example boutique"],zeilen:[["Enterprise (Unternehmen)","Legal framework – concludes business deals, pays salaries","Ms Paschinger buys, sells, pays salaries"],["Establishment (Betrieb)","Place where the goods/services are produced (an enterprise can have several)","Shop with sales area, office, storeroom"],["Company name (Firma)","Name of the enterprise (entered in the company register)","“Paschingers Moda Italia”"]]},{type:"begriff",term:"Company register",erklaerung:"Public register with the most important information about companies."},{type:"merke",text:"Enterprise = legal framework · establishment = place · company name = name. So “I'm going to the Firma” is actually wrong!"}]},{titel:"Types of business",blocks:[{type:"text",text:"Businesses are classified by 3 features: type of output, size and industry."},{type:"tabelle",spalten:["Type of output","What?","Example"],zeilen:[["Primary production (primary)","Extracting raw materials","Farm, mine"],["Manufacturing business (secondary)","Producing consumer/capital goods","Car manufacturer, steelworks"],["Service business (tertiary)","Providing goods, services","Retail, bank, insurance"]]},{type:"tabelle",spalten:["Business size","Employees"],zeilen:[["Micro business","up to 9"],["Small business","10 – 49"],["Medium-sized business","50 – 249"],["Large business","250 or more"]]},{type:"merke",text:"Size also depends on turnover (value of all sales) and balance sheet total (assets) – but usually the number of employees is counted."},{type:"begriff",term:"Industry",erklaerung:"Branch of the economy: businesses that offer the same or similar products.",beispiel:"Industry, trade & crafts, commerce, transport, banking & insurance, agriculture & forestry, tourism & leisure, information & consulting"}]},{titel:"Company goals",blocks:[{type:"begriff",term:"Goal",erklaerung:"A future state that you want to reach through planned actions."},{type:"merke",text:"Top goal: the company should survive on the market – for this it must be economically successful."},{type:"vergleich",links:{titel:"Material goal",punkte:["WHAT exactly is produced/provided","Quantity, time, quality","e.g. pastry shop: 25 Linzer tortes tomorrow"]},rechts:{titel:"Formal goal",punkte:["General economic goals","independent of the industry","e.g. increase turnover by 10%"]}},{type:"vergleich",frage:"There are 2 kinds of formal goals:",links:{titel:"Monetary (measurable in money)",punkte:["Make a profit","Secure ability to pay","Increase turnover","Reduce costs"]},rechts:{titel:"Non-monetary",punkte:["Act in an environmentally friendly way","Customer satisfaction","Working atmosphere","Image, market share"]}},{type:"ablauf",titel:"Writing goals SMART",schritte:[{titel:"S – Specific",text:"precise and clear"},{titel:"M – Measurable",text:"you can check whether it has been reached"},{titel:"A – Attractive",text:"motivates everyone involved"},{titel:"R – Realistic",text:"achievable"},{titel:"T – Time-bound",text:"by when?"}]}]},{titel:"Profit & ability to pay",blocks:[{type:"vergleich",links:{titel:"Profit-oriented",punkte:["Private companies","Successful if income > expenses"]},rechts:{titel:"Non-profit",punkte:["Work in the interest of the general public","Covering costs is enough; losses are paid e.g. by the state","e.g. public hospital, kindergarten, theatre, clubs"]}},{type:"begriff",term:"Ability to pay (liquidity)",erklaerung:"Having enough money to pay all bills on time. Applies to ALL companies."},{type:"merke",text:"Anyone who is unable to pay for a longer time puts their existence at risk – in the worst case the company has to close."}]},{titel:"Stakeholders & environments",blocks:[{type:"begriff",term:"Stakeholders (interest groups)",erklaerung:"Everyone who has an interest in what the company does – and makes demands."},{type:"vergleich",links:{titel:"Internal stakeholders",punkte:["Owners: profit, increase in value","Management: income, own ideas","Employees: income, secure job"]},rechts:{titel:"External stakeholders",punkte:["Suppliers: orders, payment","Customers: good products, low prices","Lenders: repayment, interest","Competitors: fair competition","State: taxes","Society: environmental protection"]}},{type:"merke",text:"Stakeholders' interests often conflict (employees want higher wages, owners more profit) → tensions."},{type:"tabelle",spalten:["Environment","What belongs to it?","Example"],zeilen:[["Economic","economic situation, prices","Cocoa becomes 20% more expensive"],["Social","politics, law, culture, social issues","Education level of school leavers"],["Technological","new technology, materials, processes","Fully automated production"],["Ecological","nature, raw materials, environmental protection","Solar power instead of oil"]]},{type:"begriff",term:"Sustainability",erklaerung:"Meeting today's needs without endangering future generations."}]}],zusammenfassung:[{titel:"Basic terms",punkte:["Enterprise = legal framework · establishment = place where output is produced · company name = name (in the company register)"]},{titel:"Types of business",punkte:["By output: primary production · production · services","By size: micro (≤ 9) · small (10–49) · medium (50–249) · large (250+ employees)","By industry: industry, trade/crafts, commerce, transport, banking/insurance, tourism …"]},{titel:"Company goals",punkte:["Top goal: to survive on the market","Material goal = concrete output (what, how much, when, what quality)","Formal goal = general economic goal: monetary (profit, turnover, liquidity) or non-monetary (image, environment)","SMART: specific, measurable, attractive, realistic, time-bound","Profit organisation (profit) ↔ non-profit organisation (public interest, covering costs)","All companies must secure their ability to pay (liquidity)"]},{titel:"Stakeholders & environments",punkte:["Stakeholders = interest groups with an interest in the company","Internal: owners, management, employees","External: suppliers, customers, lenders, competitors, state, society","Environments: economic, social, technological, ecological"]}]},"leistungserstellung-1jg":{schritte:[{titel:"Factors of production",blocks:[{type:"begriff",term:"Factors of production",erklaerung:"Everything a company needs to produce its goods or services: human labour + business assets."},{type:"vergleich",frage:"Human labour depends on:",links:{titel:"Ability (being able to)",punkte:["Talent","Training","Work experience","Age"]},rechts:{titel:"Willingness (wanting to = motivation)",punkte:["Pay","Workplace","Working atmosphere","Working hours, praise"]}},{type:"begriff",term:"Fixed assets",erklaerung:"Stay in the company for a LONG time (longer than 1 year) and keep the business running in the long term."},{type:"tabelle",spalten:["Fixed assets","Examples"],zeilen:[["Tangible fixed assets (equipment)","Land, buildings, machines, vehicles, office equipment"],["Financial assets","Securities, shareholdings"],["Intangible","Brands, patents, software"]]},{type:"begriff",term:"Current assets",erklaerung:"Stay in the company only for a SHORT time because they are constantly used up or sold."},{type:"tabelle",spalten:["Current assets","Meaning","Example jeans"],zeilen:[["Raw materials","Main component","Denim fabric"],["Auxiliary materials","Secondary component","Thread"],["Operating supplies","Are used up, not part of the product","Oil for the sewing machine"],["Merchandise","Bought ready-made, resold unchanged","Belt"],["Finished/unfinished products","Made in-house","Finished jeans"],["Financial current assets","Money & claims","Cash, bank balance, receivables"]]},{type:"merke",text:"Raw materials, auxiliary materials and operating supplies together are called materials. Trick: there for a long time → fixed; used up/sold → current."}]},{titel:"Areas of the company",blocks:[{type:"text",text:"A company is divided into departments (functional areas). The 3 basic functions are directly linked to the product:"},{type:"kette",glieder:[{titel:"Suppliers → 1.",wert:"Procurement"},{titel:"2.",wert:"Production"},{titel:"3. → customers",wert:"Sales"}]},{type:"text",text:"They are supported by the warehouse, HR and accounting. Management is above everything."},{type:"tabelle",spalten:["Area","Task"],zeilen:[["Procurement (purchasing)","Ensuring the supply of all necessary materials"],["Production","Combining factors of production, producing goods"],["Sales (distribution)","Selling with targeted marketing – as much turnover as possible"],["Warehouse","Providing goods on time"],["Human resources","Everything to do with the employees"],["Accounting","Recording business processes in figures, checking them"],["Management","Running the whole company"]]},{type:"begriff",term:"Turnover (revenue)",erklaerung:"Total value of all goods sold in a certain period.",beispiel:"Turnover = quantity sold · price"}]},{titel:"Warehouse & human resources",blocks:[{type:"ablauf",titel:"Types of warehouse in sequence",schritte:[{titel:"Procurement warehouse",text:"Purchased materials for production"},{titel:"Intermediate warehouse",text:"Unfinished goods between production steps"},{titel:"Sales and shipping warehouse",text:"Finished products before they are sold"}]},{type:"ablauf",titel:"Tasks of human resources",schritte:[{titel:"Planning staff requirements"},{titel:"Recruiting staff"},{titel:"Concluding and ending employment contracts"},{titel:"Developing employees (training and further education)"},{titel:"Calculating wages and salaries"}]},{type:"merke",text:"Personnel management is often called Human Resource Management (HR) today."}]},{titel:"Management",blocks:[{type:"begriff",term:"Management",erklaerung:"Runs the company. Its tasks repeat in the management cycle:"},{type:"zyklus",mitte:"Management",schritte:["Setting goals & planning","Deciding","Organising & steering","Controlling"]},{type:"text",text:"Example: goal “turnover for women's jeans +5%” → decide on measures → implement them with the departments → check at the end of the year whether it worked."}]}],zusammenfassung:[{titel:"Factors of production",punkte:["Human labour (ability + willingness) + business assets","Fixed assets = long-term: tangible assets, financial assets, intangible assets (patents, brands)","Current assets = short-term: raw, auxiliary and operating materials (= materials), merchandise, products, cash/bank/receivables"]},{titel:"Areas of the company",punkte:["Basic functions: procurement → production → sales","Support: warehouse, HR, accounting · above them: management","Turnover = quantity sold · price","Types of warehouse: procurement, intermediate, sales/shipping warehouse","Management cycle: plan → decide → organise/steer → control"]}]},"phasen-kaufen-verkaufen":{schritte:[{titel:"The purchase contract at a glance",blocks:[{type:"begriff",term:"Purchase contract",erklaerung:"Contract between seller and buyer about an item (physical good or service). Every time you buy something, you conclude one!"},{type:"ablauf",titel:"The 3 phases",schritte:[{titel:"Initiation",text:"Seller and buyer find each other (advertisement, enquiry, offer)"},{titel:"Conclusion",text:"Both agree (order, order confirmation)"},{titel:"Fulfilment",text:"Seller delivers, buyer pays"}]},{type:"merke",text:"In the supermarket all 3 phases happen in seconds. When buying a house they take weeks (with a notary)."}]},{titel:"Initiation: advertisement & enquiry",blocks:[{type:"text",text:"In the initiation phase the most important information is exchanged: Who is selling? What quality, quantity, which price?"},{type:"begriff",term:"Advertisement (from the seller)",erklaerung:"Advertising aimed at many people (brochure, TV ad, online ad). The seller wants to attract attention but is NOT bound – there is no intention to be bound.",beispiel:"“While stocks last”, “non-binding”, “prices subject to change”"},{type:"begriff",term:"Enquiry (from the buyer)",erklaerung:"The buyer asks for specific information. It is non-binding – he does not have to buy anything. Any form is allowed (oral or written)."},{type:"vergleich",links:{titel:"General enquiry",punkte:["No exact wishes","Wants an overview (catalogue, price list)","“Please send me a catalogue.”"]},rechts:{titel:"Specific enquiry",punkte:["Concrete wishes","Usually wants an offer","“Do you have laptop XY? How much is it?”"]}}]},{titel:"Initiation: offer & order",blocks:[{type:"begriff",term:"Offer",erklaerung:"The seller says: “I want to sell you this on these terms.” Can be unsolicited (without an enquiry) or solicited (after an enquiry)."},{type:"entscheidung",titel:"Is the offer binding?",schritte:[{frage:"Does it name seller, buyer, quality, quantity and price?",links:{antwort:"No",ergebnis:"Only an advertisement",beispiel:"not binding"},rechts:{antwort:"Yes",weiter:"keep checking"}},{frage:"Does the seller clearly want to sell (intention to be bound)?",links:{antwort:"No",ergebnis:"Without obligation",beispiel:"“without obligation”, “while stocks last”"},rechts:{antwort:"Yes",weiter:"keep checking"}},{frage:"Has it reached the buyer personally?",links:{antwort:"No",ergebnis:"Not binding yet"},rechts:{antwort:"Yes",ergebnis:"Binding offer",beispiel:"Seller must deliver"}}]},{type:"tabelle",spalten:["How long is it valid?","Period of validity"],zeilen:[["Period stated","as long as stated (e.g. “2 weeks from receipt”)"],["Oral, nothing stated","only during the conversation"],["Letter, nothing stated","time to consider + two postal journeys (4–6 days)"],["E-mail, nothing stated","only a reasonable time to consider"]]},{type:"begriff",term:"Exemption clause",erklaerung:"With it the seller makes his offer non-binding (without obligation)."},{type:"begriff",term:"Order",erklaerung:"The buyer offers to buy a certain product. If there was an offer before, the order is already part of the conclusion."}]},{titel:"Concluding the purchase contract",blocks:[{type:"kette",glieder:[{titel:"Seller",wert:"Offer"},{titel:"Buyer",wert:"Acceptance"},{titel:"Result",wert:"Contract ✓"}]},{type:"begriff",term:"Mutual declaration of intent",erklaerung:"Seller and buyer want exactly the same thing on the same terms. Then the contract is concluded."},{type:"tabelle",spalten:["Form","Example"],zeilen:[["Oral","Ordering pizza by phone"],["Written","Buying a Tesla, made-to-measure furniture"],["Electronic","Online shop (order button)"],["Implied conduct","Putting money into a drinks machine"],["Tacit","only between businesses with a long business relationship"]]},{type:"merke",text:"In principle there is freedom of form. Must be in writing: land, houses, flats and instalment purchases. Silence from a private person = rejection – you neither have to pay for nor return goods you did not order!"}]},{titel:"Valid contract & legal capacity",blocks:[{type:"tabelle",spalten:["Requirement","Meaning"],zeilen:[["Two parties","at least 2 partners"],["Mutual declaration of intent","both agree on all terms"],["Voluntariness","nobody is forced or threatened"],["Legality","no breach of the law (e.g. drug dealing)"],["Possibility","nothing impossible (a plot of land on Jupiter)"],["Legal capacity","minimum age and full mental capacity"]]},{type:"begriff",term:"Legal capacity",erklaerung:"The ability to conclude valid contracts yourself. Depends on age and state of mind."},{type:"ablauf",titel:"Levels of legal capacity",schritte:[{titel:"Under 7: no legal capacity",text:"only pocket-money purchases (ice cream, comics)"},{titel:"7–14: limited legal capacity",text:"minor everyday purchases, accepting gifts"},{titel:"14–18: extended limited capacity",text:"up to the amount of pocket money/own earnings, if their living is not endangered (clothes, phone)"},{titel:"From 18: full legal capacity",text:"all permitted transactions (car, holiday)"}]},{type:"merke",text:"If a minor goes beyond this, the contract is provisionally invalid – only valid with the parents' consent."}]},{titel:"Fulfilling the purchase contract",blocks:[{type:"vergleich",links:{titel:"Seller's duties",punkte:["Deliver the product (on time, at the agreed place)","Issue a proper invoice"]},rechts:{titel:"Buyer's duties",punkte:["Accept the product (even if it is cheaper elsewhere)","Pay (immediately or within the agreed period)"]}},{type:"merke",text:"The buyer's rights are the seller's duties – and vice versa. Keep proof of payment (evidence, guarantee)!"},{type:"ablauf",titel:"Checking the invoice: Is … correct?",schritte:[{titel:"the invoice date"},{titel:"the recipient"},{titel:"the delivery date"},{titel:"the product description"},{titel:"the price"},{titel:"the rest (discount, guarantee …)"}]}]}],zusammenfassung:[{titel:"Phases",punkte:["Initiation → conclusion → fulfilment"]},{titel:"Initiation",punkte:["Advertisement = advertising to many people, non-binding (no intention to be bound)","Enquiry = buyer gathers information, non-binding; general (overview) or specific (concrete)","Offer: unsolicited or solicited; binding if specific in content (seller, buyer, quality, quantity, price) + intention to be bound + received personally","Validity: as stated · oral = during conversation · letter = time to consider + two postal journeys · e-mail = time to consider","Exemption clause → offer without obligation"]},{titel:"Conclusion",punkte:["Contract through mutual declaration of intent (offer + timely acceptance)","Forms: oral, written, electronic, implied, tacit","Must be in writing: land, flats, instalment purchases","Valid if: two parties, agreement, voluntariness, legality, possibility, legal capacity","Legal capacity: < 7 none · 7–14 limited · 14–18 extended limited · from 18 full"]},{titel:"Fulfilment",punkte:["Seller: deliver + invoice · buyer: accept + pay"]}]},"gesetzliche-grundlagen-kauf":{schritte:[{titel:"Contracting parties & types of business",blocks:[{type:"begriff",term:"Contract",erklaerung:"Agreement about a deal between 2 or more partners – with legal consequences. So think carefully!"},{type:"text",text:"Who concludes a contract with whom determines the type of business:"},{type:"tabelle",spalten:["Type of business","Seller → buyer","Example"],zeilen:[["C2C (consumer-to-consumer)","Private → private","Selling an old phone on eBay"],["B2C (business-to-consumer)","Company → private","Buying a cake at the pastry shop"],["B2B (business-to-business)","Company → company","Billa buys milk from Schärdinger"]]},{type:"merke",text:"Business = company, consumer = private person."}]},{titel:"Applicable laws",blocks:[{type:"text",text:"In principle there is freedom of content – you may freely decide what the contract says. But these laws still apply:"},{type:"tabelle",spalten:["Law","For what?"],zeilen:[["ABGB (Austrian Civil Code)","for ALL contracts (e.g. legal capacity)"],["KSchG (Consumer Protection Act)","protects private persons from unfair practices by companies"],["UGB (Austrian Commercial Code)","contracts between companies"],["ECG (E-Commerce Act)","sellers with a website/online presence"],["FAGG (Distance and Off-Premises Contracts Act)","business ↔ private person outside the business premises"],["GDPR (General Data Protection Regulation)","handling of personal data in the EU"]]},{type:"tabelle",spalten:["Type of business","Important laws"],zeilen:[["C2C","ABGB, ECG (if online)"],["B2C","ABGB, KSchG, FAGG, ECG (if online), GDPR"],["B2B","ABGB, UGB, ECG (if online), GDPR"]]},{type:"merke",text:"The ABGB always applies. The KSchG only if a consumer is involved (B2C). The UGB only between companies (B2B)."},{type:"begriff",term:"Trade customs (Usancen)",erklaerung:"Commercial customs in B2B – rules everyone knows that do not have to be agreed every time."}]},{titel:"Other types of contract",blocks:[{type:"tabelle",spalten:["Type of contract","Performance","Consideration"],zeilen:[["Purchase contract","Product","Purchase price"],["Contract for work","Work (e.g. a repair)","Payment for the work"],["Rental contract","Rented item","Rent"],["Employment contract","Work performance","Wage, salary"],["Loan agreement","Amount of money","Interest + repayment"],["Insurance contract","Payment in case of damage","Insurance premium"]]},{type:"merke",text:"There are also mixed contracts that combine several types."}]}],zusammenfassung:[{titel:"Types of business",punkte:["Contract = agreement between 2+ partners with legal consequences","C2C (private–private) · B2C (company–private) · B2B (company–company)"]},{titel:"Laws",punkte:["ABGB: all contracts · KSchG: consumer protection · UGB: between companies","ECG: online presence · FAGG: distance and off-premises contracts · GDPR: data protection","C2C: ABGB (+ECG) · B2C: ABGB, KSchG, FAGG, GDPR (+ECG) · B2B: ABGB, UGB, GDPR (+ECG)"]},{titel:"Types of contract",punkte:["Purchase (product ↔ price) · work (work ↔ payment) · rental (item ↔ rent)","Employment (work ↔ wage) · loan (money ↔ interest + repayment) · insurance (cover ↔ premium)"]}]},"fernabsatz-ecommerce":{schritte:[{titel:"Distance selling & e-commerce",blocks:[{type:"begriff",term:"Distance selling",erklaerung:"Buyer and seller NEVER meet in person. All 3 phases take place via means of distance communication.",beispiel:"Internet, phone, e-mail, catalogue, letters"},{type:"begriff",term:"E-commerce (electronic commerce)",erklaerung:"All the trading takes place over the internet (website, online shop). E-commerce is a special form of distance selling."},{type:"merke",text:"Negotiated in the shop first and then concluded by phone? Not distance selling – ALL phases must take place at a distance."},{type:"ablauf",titel:"How an online purchase works",schritte:[{titel:"Put products in the shopping basket"},{titel:"Enter personal details and payment method"},{titel:"Click the order button",text:"= contract concluded!"}]}]},{titel:"Risks of online shopping",blocks:[{type:"tabelle",spalten:["Risk","What can happen?"],zeilen:[["Risk of fraud","Seller disappears after payment, never delivers (fake shop)"],["No inspection","Only pictures and reviews – these can be fake"],["Data misuse","Hackers steal account details"]]}]},{titel:"Seller's duties",blocks:[{type:"text",text:"To protect buyers, the seller must comply with the law (KSchG, FAGG, ECG)."},{type:"begriff",term:"Duty to inform",erklaerung:"In the legal notice: name/company, address, contact, VAT number, supervisory authority, company register number, chamber. Before the contract: product features, price incl. taxes, delivery/payment, right of withdrawal, warranty. Terms and conditions must be easy to find."},{type:"begriff",term:"Duty to confirm",erklaerung:"It must be clear that the order button triggers a purchase (“Order now with obligation to pay”). An order confirmation must follow."},{type:"begriff",term:"Delivery period",erklaerung:"At the latest 30 days after the contract is concluded. If not possible, inform the buyer immediately and refund the money."},{type:"begriff",term:"Right of withdrawal",erklaerung:"The buyer must be informed about the right to withdraw."}]},{titel:"Shopping safely online",blocks:[{type:"ablauf",titel:"9 tips",schritte:[{titel:"Check seller and product",text:"Company or private person?"},{titel:"Choose certified shops from the EU",text:"e.g. with an e-commerce quality seal"},{titel:"Read the terms and conditions"},{titel:"Save the order confirmation and terms"},{titel:"Be suspicious of free offers",text:"often bait offers with ongoing costs"},{titel:"Don't pay in advance"},{titel:"Watch out for shipping and packaging costs"},{titel:"If there are problems: consumer protection",text:"e.g. konsument.at"},{titel:"Encrypted connection",text:"“https://” and padlock symbol"}]},{type:"begriff",term:"Electronic signature (digital signature)",erklaerung:"Is just as valid as a handwritten signature. In Austria with the ID Austria (successor to the mobile phone signature)."}]}],zusammenfassung:[{titel:"Terms",punkte:["Distance selling = all phases only via means of distance communication (internet, phone, e-mail, catalogue, letter)","E-commerce = trading over the internet; contract by clicking the order button","Risks: fraud, no inspection, data misuse"]},{titel:"The seller must …",punkte:["Duty to inform: legal notice (name, address, contact, VAT no., company register no.) + product, price, delivery, right of withdrawal; terms easy to find","Duty to confirm: clear order button + order confirmation","Delivery period: max. 30 days","inform about the right of withdrawal"]},{titel:"Tips",punkte:["Certified EU shops, read the terms, save receipts, don't pay in advance, look for https","Digital signature: ID Austria (Signature Act)"]}]},ruecktrittsrechte:{schritte:[{titel:"Basic rules",blocks:[{type:"merke",text:"Once a purchase contract has been validly concluded, there is in principle NO going back. Both sides must fulfil it."},{type:"text",text:"But there are 3 ways to end a contract anyway:"},{type:"begriff",term:"Amendment",erklaerung:"Termination by mutual agreement (return, both agree) or exchange for another product."},{type:"merke",text:"There is NO right to exchange in the law! It must be agreed (in the purchase contract or on the receipt). The seller may also just give a voucher."},{type:"begriff",term:"Withdrawal",erklaerung:"Only possible if: a right of withdrawal was expressly agreed · the contract is unlawful (e.g. lack of legal capacity) · fraudulent deception · default (e.g. the seller does not deliver on time)."},{type:"begriff",term:"Fraudulent",erklaerung:"Deliberately malicious – e.g. the seller intentionally hides a defect."},{type:"begriff",term:"Cancellation",erklaerung:"Undoing a contract, usually for a cancellation fee (stated in the contract or terms and conditions).",beispiel:"Cancelling a holiday due to illness"}]},{titel:"Special rights of withdrawal",blocks:[{type:"text",text:"Consumers have special rights of withdrawal – because you can be taken by surprise in some deals."},{type:"begriff",term:"When do they apply?",erklaerung:"For deals OUTSIDE the business premises (doorstep sale, promotional trip) and in DISTANCE SELLING (online shop)."},{type:"merke",text:"Withdrawal WITHOUT giving reasons and WITHOUT a cancellation fee! But a trade fair stand counts as business premises."},{type:"tabelle",spalten:["Situation","Withdrawal period"],zeilen:[["Informed, goods handed over immediately","14 calendar days from conclusion of contract"],["Informed, goods are delivered","14 calendar days from delivery"],["NOT informed about the right of withdrawal","1 year + 14 calendar days"]]},{type:"text",text:"Example: jacket ordered online, delivered on 7 August → withdrawal possible until 21 August."}]},{titel:"Procedure & exceptions",blocks:[{type:"begriff",term:"Form of withdrawal",erklaerung:"No particular form required – but in writing is better as proof."},{type:"ablauf",titel:"After withdrawal",schritte:[{titel:"Buyer pays for return shipping",text:"if he was informed about it"},{titel:"Used/consumed?",text:"Seller may demand compensation"},{titel:"Seller refunds the money"}]},{type:"tabelle",spalten:["NO withdrawal for …","Example"],zeilen:[["Home delivery of food","Pizza"],["Custom-made items","tailor-made dress, photo book"],["Software, CDs, DVDs with broken seal","–"],["Urgent repairs on request","Plumber called out"],["Leisure services with a fixed date","Theatre tickets, plane tickets"]]}]}],zusammenfassung:[{titel:"Principle",punkte:["Valid contract = no going back","Amendment: termination by mutual agreement or exchange (NO legal right to exchange!)","Withdrawal only if: agreed, unlawful, fraudulent deception, default","Cancellation: usually with a cancellation fee"]},{titel:"Special rights of withdrawal (consumers)",punkte:["For deals outside the business premises and in distance selling","Without reasons and without a cancellation fee; any form (writing recommended)","Period: 14 days from conclusion/delivery · not informed: 1 year + 14 days","Exceptions: food delivery, custom-made items, opened software, urgent repairs, tickets"]}]},"bestandteile-kaufvertrag":{schritte:[{titel:"Overview",blocks:[{type:"text",text:"In deals between companies (B2B) a lot is regulated to avoid disputes. There are 3 groups of elements:"},{type:"tabelle",spalten:["Group","Content","Mandatory?"],zeilen:[["Statutory elements","Seller, buyer, quality, quantity, price","MUST always be agreed"],["Regular commercial elements","Delivery terms, payment terms","can be added"],["Other commercial elements","Retention of title, penalty, cancellation fee, guarantee, exchange, packaging, additional services","can be added"]]}]},{titel:"Quality",blocks:[{type:"vergleich",links:{titel:"Fungible",punkte:["Can be replaced by an equivalent","One item shows the quality of all","e.g. phone, A4 exercise book"]},rechts:{titel:"Non-fungible",punkte:["Unique","Must be inspected/described exactly","e.g. work of art, plot of land, used car"]}},{type:"tabelle",spalten:["Specifying quality","Explanation"],zeilen:[["Inspection","Buyer checks it himself (“as inspected”) – mainly one-off items"],["Description, illustration","Features in text and pictures (online shop)"],["Samples, trial quantities","small quantities for testing"],["Brands, models","Brand = protected sign (word, image, combined); model = type (iPhone 15)"],["Standards, quality grades, quality seals","ÖNORM/DIN A4 · apples class Extra · AMA quality seal"],["Purchase by specification","The buyer specifies details (size, colour) later"],["Purchase in bulk (Bausch und Bogen)","all the goods for one price, regardless of defects (whole harvest)"]]},{type:"tabelle",spalten:["Type of sample purchase","Meaning","Example"],zeilen:[["Purchase by sample","Goods must be like the sample","Tile sample"],["Purchase on approval","can be returned within a period","Mattress"],["Trial purchase","test a small quantity cheaply, no returns","Wall paint"]]}]},{titel:"Quantity",blocks:[{type:"tabelle",spalten:["Quantity stated","Example"],zeilen:[["Exact","50 kg cement, 100 pairs of shoes"],["Approximate (“about” + deviation)","approx. 3,000 kg gravel ± 5%"],["None (in bulk)","entire future wine harvest"]]},{type:"kette",glieder:[{titel:"Product only",wert:"Net"},{titel:"+ packaging",wert:"Tare"},{titel:"= total",wert:"Gross"}]},{type:"vergleich",links:{titel:"Extra goods (Draufgabe)",punkte:["More delivered than paid for","10 m³ paid, 11 m³ delivered"]},rechts:{titel:"Free quantity (Dreingabe)",punkte:["Less charged than delivered","10 m³ delivered, 9 m³ charged"]}}]},{titel:"Price, discount & cash discount",blocks:[{type:"vergleich",links:{titel:"Fixed price",punkte:["Stated exactly, will not be changed"]},rechts:{titel:"Variable price",punkte:["Market/exchange price (heating oil, gold)","Value protection clause (linked to the consumer price index)","Base purchase (guide price depending on quality)","Cost fluctuation clause (house building)"]}},{type:"begriff",term:"Discount (Rabatt)",erklaerung:"Price reduction for a specific reason."},{type:"tabelle",spalten:["Reason","Types of discount"],zeilen:[["Large quantity","Quantity discount, end-of-period discount, discount in kind (extra/free goods), turnover bonus (at year end)"],["Loyal customers","Loyalty discount"],["Special events","Launch, clearance, defect discount"]]},{type:"begriff",term:"Cash discount (Skonto)",erklaerung:"Price deduction for paying quickly (before the due date). Usually 2–5%.",beispiel:"“30 days net or 7 days with 3% cash discount”"},{type:"merke",text:"Discount = for a reason. Cash discount = for quick payment. B2B: prices without VAT (net). B2C: prices incl. VAT (gross)."}]},{titel:"Price calculation",blocks:[{type:"begriff",term:"Purchase calculation",erklaerung:"Calculates the cost price = what the product really costs me when buying it."},{type:"tabelle",spalten:["Purchase calculation","Example: 30 T-shirts"],zeilen:[["List purchase price (excl. VAT)","285.00"],["− supplier discount (20%)","− 57.00"],["= target purchase price","228.00"],["− supplier cash discount (2%)","− 4.56"],["= cash purchase price","223.44"],["+ acquisition costs","+ 20.50"],["= cost price","243.94 (1 item: 8.13)"]]},{type:"begriff",term:"Sales calculation",erklaerung:"Calculates the selling price incl. VAT, starting from the cost price."},{type:"tabelle",spalten:["Sales calculation","Example: 1 T-shirt"],zeilen:[["Cost price","8.13"],["+ overheads (30% – own costs: rent, staff …)","+ 2.44"],["= cost of goods","10.57"],["+ profit (20%)","+ 2.11"],["= cash selling price","12.68"],["+ customer cash discount (2%, “in hundred”)","+ 0.26"],["= target selling price","12.94"],["+ customer discounts (“in hundred”)","+ 1.10"],["= net selling price","14.04"],["+ VAT (20%)","+ 2.81"],["= gross selling price","16.85"]]},{type:"merke",text:"In the sales calculation, calculate cash discounts and discounts “in hundred”: value · percentage / (100 − percentage). Calculate several discounts one after another!"}]},{titel:"Delivery terms",blocks:[{type:"tabelle",spalten:["Time of fulfilment","Meaning","Example"],zeilen:[["Spot transaction","immediately (applies if nothing is agreed)","–"],["Fixed-date transaction","exact date or purpose","“fixed on 20 April”, wedding cake"],["Ordinary forward transaction","approximate date","“within 2 weeks”"],["Purchase on call","large quantity, call off parts as needed","–"]]},{type:"begriff",term:"Place of fulfilment",erklaerung:"Place where the goods are handed over – ownership, risk and costs pass to the buyer there."},{type:"text",text:"Handover can be physical (shoes), symbolic (keys, warehouse receipt) or electronic (download). If nothing is agreed: B2B = handover to the carrier, B2C = handover to the buyer."},{type:"transportweg",titel:"“Ex works” (one-point clause) – good for the seller",stationen:["Seller","Station A","Station B","Buyer"],risiko:0,kosten:0},{type:"transportweg",titel:"“Free domicile” (one-point clause) – good for the buyer",stationen:["Seller","Station A","Station B","Buyer"],risiko:3,kosten:3},{type:"transportweg",titel:"“Carriage paid to station B” (two-point clause)",stationen:["Seller","Station A","Station B","Buyer"],risiko:0,kosten:2},{type:"merke",text:"One-point clause: risk and costs at the SAME place. Two-point clause: at TWO places (risk already with the first carrier). International clauses are called Incoterms."}]},{titel:"Payment terms",blocks:[{type:"tabelle",spalten:["Time of payment","When?","Example"],zeilen:[["Payment in advance","before delivery","Online shop, custom-made item"],["Prompt payment (cash purchase)","on delivery (applies if nothing is agreed)","“payable without deduction on receipt”"],["Later payment (credit purchase)","after delivery","“8 days 3% cash discount, 30 days net”"],["Instalment purchase","in instalments","12 monthly instalments (most expensive form of credit!)"]]},{type:"begriff",term:"Payment term & discount period",erklaerung:"Payment term = deadline by which payment must be made. Discount period = shorter period for deducting the cash discount."},{type:"begriff",term:"Annual interest rate of the cash discount",erklaerung:"Cash discount % / (payment term − discount period) · 360",beispiel:"3 / (30 − 8) · 360 = 49.09% p.a. → using the cash discount almost always pays off, even with a bank loan!"},{type:"begriff",term:"Place of fulfilment for payment",erklaerung:"Money debts must be brought to the creditor: the buyer brings/transfers the money to the seller's place of business and pays the transfer fees."}]},{titel:"Other elements & terms and conditions",blocks:[{type:"tabelle",spalten:["Element","Meaning"],zeilen:[["Retention of title","Goods belong to the seller until everything is paid"],["Penalty (contractual penalty)","Penalty for the seller if delivery is too late"],["Cancellation fee (forfeit money)","Buyer may withdraw for a fee"],["Guarantee","voluntary: seller is liable for defects within the guarantee period"],["Right to exchange","not mandatory, only if agreed"],["Packaging","Costs are paid by the buyer (usually included in the price)"],["Additional services","Installation, training, updates"]]},{type:"begriff",term:"Functions of packaging",erklaerung:"Protection · transport and storage · sales promotion/advertising · information/guarantee · smart packaging (freshness code)."},{type:"begriff",term:"Terms and conditions (AGB)",erklaerung:"Pre-written contract terms for many purchase contracts (“the small print”), e.g. delivery and payment terms, guarantee, exchange."},{type:"merke",text:"Terms and conditions only apply if the buyer could know them BEFORE the contract was concluded. They must be clear and must not unfairly disadvantage the buyer."}]}],zusammenfassung:[{titel:"Statutory elements",punkte:["Seller, buyer, quality, quantity, price – must always be agreed","Quality: fungible (replaceable) ↔ non-fungible (unique); specified by inspection, description, samples, brands/models, standards/quality seals","Purchase by sample · on approval (return) · trial purchase (test, no return)","Quantity: exact, approximate, none (in bulk) · net + tare = gross · extra goods / free quantity","Price: fixed or variable · discount (for a reason) · cash discount (quick payment)"]},{titel:"Calculation",punkte:["Purchase: list price − discount − cash discount + acquisition costs = cost price","Sales: cost price + overheads + profit + cash discount + discounts + VAT = gross selling price","Cash discount/discount in sales “in hundred”: · % / (100 − %)"]},{titel:"Delivery & payment terms",punkte:["Delivery time: spot · fixed-date · forward transaction · purchase on call","Place of fulfilment = transfer of ownership, risk, costs","Ex works (buyer bears everything) · free domicile (seller bears everything) · carriage paid … (two-point clause)","Payment: in advance · cash purchase · credit purchase · instalments","Cash discount annual rate = discount% / (term − discount period) · 360","Money debts must be brought to the creditor"]},{titel:"Other & terms and conditions",punkte:["Retention of title, penalty, cancellation fee, guarantee, exchange, packaging, additional services","Terms and conditions = pre-written contract terms; must be known before conclusion and be clear"]}]},"schriftverkehr-kaufvertrag":{schritte:[{titel:"The process at a glance",blocks:[{type:"text",text:"Between companies (B2B) every phase is documented in writing. This is called business correspondence."},{type:"ablauf",titel:"From offer to invoice",schritte:[{titel:"Advertisement (seller)",text:"Catalogue, advertising – non-binding"},{titel:"Enquiry (buyer)",text:"Requesting information or an offer – non-binding"},{titel:"Offer (seller)",text:"binding: wants to sell on these terms"},{titel:"Order (buyer)",text:"Order placed with the supplier"},{titel:"Order confirmation (seller)",text:"repeats all details"},{titel:"Delivery with delivery note/receipt copy"},{titel:"Invoice → check → payment"}]},{type:"merke",text:"Every letter answers 2 questions: “Why am I writing?” (reason) and “What do I want?” (goal)."}]},{titel:"Enquiry",blocks:[{type:"vergleich",frage:"Where does the buyer find suppliers?",links:{titel:"Inside the company",punkte:["Own supplier file (information on previous suppliers)"]},rechts:{titel:"Outside the company",punkte:["Advertisements (catalogues, promotional e-mails)","Business contacts","Trade fairs","Supplier search engines (wlw.at)","Chamber of Commerce (wko.at)"]}},{type:"ablauf",titel:"Enquiry checklist",schritte:[{titel:"State the purpose"},{titel:"Describe your needs clearly"},{titel:"List the information needed",text:"general (catalogue) or specific (quality, price, terms)"},{titel:"Ask for an offer/information"},{titel:"Name a contact person"},{titel:"Set the form and deadline for the reply"}]},{type:"merke",text:"Enquiries are non-binding and not tied to any form."}]},{titel:"Offer & comparison of offers",blocks:[{type:"begriff",term:"Offer",erklaerung:"The seller shows that he wants to conclude a specific deal. The clearer it is worded, the less dispute later."},{type:"ablauf",titel:"Offer checklist",schritte:[{titel:"Say thank you (solicited) or state the reason (unsolicited)"},{titel:"Describe the product exactly, quantity, price, VAT"},{titel:"Time limit/restriction"},{titel:"Delivery and payment terms"},{titel:"Reference to terms and conditions, enclosures"},{titel:"Hope for a deal"}]},{type:"vergleich",frage:"Comparing offers:",links:{titel:"Comparing prices only",punkte:["→ cheapest supplier"]},rechts:{titel:"Also quality, delivery time, terms, service, punctuality",punkte:["→ best supplier"]}},{type:"begriff",term:"Counter-offer",erklaerung:"The buyer does not agree with some terms and proposes his own. The seller decides whether to accept."}]},{titel:"Order & order confirmation",blocks:[{type:"begriff",term:"Order",erklaerung:"Instruction to the supplier to deliver a specific product. No set form, but usually in writing."},{type:"entscheidung",titel:"When is the contract concluded?",schritte:[{frage:"What is the order based on?",links:{antwort:"Binding offer",ergebnis:"Immediately with the order",beispiel:"Order confirmation only confirms"},rechts:{antwort:"Advertisement / non-binding",ergebnis:"Only with the order confirmation",beispiel:"Seller can still make changes"}}]},{type:"begriff",term:"Order confirmation",erklaerung:"The seller confirms the order and repeats all details to avoid mistakes."},{type:"vergleich",links:{titel:"AFTER conclusion",punkte:["Order after a binding offer","Only a confirmation, not strictly necessary"]},rechts:{titel:"AS conclusion",punkte:["Order after an advertisement/non-binding offer","The contract is ONLY formed with it"]}}]},{titel:"Delivery & invoice",blocks:[{type:"vergleich",frage:"Duties when fulfilling the contract:",links:{titel:"Seller",punkte:["Deliver the products","Issue the invoice"]},rechts:{titel:"Buyer",punkte:["Accept the products","Pay"]}},{type:"tabelle",spalten:["Accompanying document","Meaning"],zeilen:[["Delivery note","lists the products delivered (WITHOUT prices), stays with the buyer"],["Receipt copy (Gegenschein)","copy; the buyer confirms receipt with a signature, goes back to the seller"],["Freight documents","only if a carrier delivers (rail, lorry)"]]},{type:"begriff",term:"Invoice",erklaerung:"Bills the delivery. Under the VAT Act it must contain e.g.: name/address of seller & buyer, delivery date, quantity & description, net price, VAT rate and amount, date of issue, consecutive number, VAT ID number."},{type:"begriff",term:"Small-amount invoice",erklaerung:"Up to €400 gross fewer details are enough: seller, date, quantity/description, total incl. VAT, tax rate, delivery date."},{type:"zyklus",mitte:"Receiving goods",schritte:["Accept & check the product","Store it","Check the invoice","Approve payment"]},{type:"merke",text:"Note visible defects immediately on the delivery note and receipt copy! In B2B, payment is by bank transfer, not cash."}]}],zusammenfassung:[{titel:"Process",punkte:["Advertisement → enquiry → offer → order → order confirmation → delivery → invoice → payment","Every letter: “Why am I writing?” + “What do I want?”"]},{titel:"Initiation",punkte:["Sources of information: internal (supplier file) · external (trade fairs, catalogues, wlw.at, Chamber of Commerce)","Enquiry: non-binding, no set form","Comparing offers: price only = cheapest · with quality/service/delivery time = best supplier","Counter-offer: buyer changes the terms"]},{titel:"Conclusion",punkte:["Order after a binding offer → contract immediately; order confirmation AFTER conclusion","Order after an advertisement → contract only through the order confirmation (AS conclusion)"]},{titel:"Fulfilment",punkte:["Seller: deliver + invoice · buyer: accept + pay","Delivery note (no prices) · receipt copy (signature, sent back) · freight documents","Invoice according to the VAT Act; small-amount invoice up to €400 gross","Receiving goods: check → store → check invoice → approve payment"]}]},"zahlungsformen-1jg":{schritte:[{titel:"Overview & cash payment",blocks:[{type:"tabelle",spalten:["Method of payment","Examples"],zeilen:[["Cash payment","Coins, banknotes"],["With a current account","Payment slip, SEPA standing order, SEPA direct debit, cash on delivery"],["Payment cards","Debit card, credit card, prepaid card"],["With the computer","E-banking, online shopping (PayPal, Klarna, eps …)"],["With the phone","M-payment (banking apps, Apple Pay)"]]},{type:"begriff",term:"Cash payment",erklaerung:"The debtor gives the creditor money in coins or banknotes – directly between two people."},{type:"vergleich",links:{titel:"Advantages",punkte:["Simple","Overview of spending","Anonymous","No fees","Money available immediately"]},rechts:{titel:"Disadvantages",punkte:["Personal meeting necessary","Risk of loss and theft","Inconvenient (small change, counting)"]}},{type:"begriff",term:"Proof of payment",erklaerung:"Every business must issue a receipt for cash payments: till receipt (cash register), payment note (“amount received with thanks”) or receipt."},{type:"begriff",term:"Checking for counterfeit money",erklaerung:"“Feel – look – tilt”: raised print, watermark, hologram, emerald number (changes colour), security thread. Suspicious? Don't pass it on, take it to the bank!"}]},{titel:"Current account",blocks:[{type:"begriff",term:"Current account",erklaerung:"Bank account you use for your payments. “Giro” = circle (flow) of money."},{type:"tabelle",spalten:["Type of payment","Who has an account?","Example"],zeilen:[["Cashless","both","Bank transfer, card, e-banking"],["Semi-cash","only one","Paying a payment slip in cash, cash on delivery, cash order"]]},{type:"ablauf",titel:"Opening an account",schritte:[{titel:"Fill in the application form",text:"who has power of disposal?"},{titel:"Identification",text:"official photo ID"},{titel:"Give a specimen signature"}]},{type:"tabelle",spalten:["Term","Meaning"],zeilen:[["Power of disposal","Account holder, may do everything (even close the account)"],["Signing authority","may withdraw and deposit money, set up standing orders – not close it"],["Single account","one person with power of disposal"],["Joint account (either-or)","several people, each may act alone"],["Joint account (both)","several people, only together"]]},{type:"vergleich",links:{titel:"Debit interest",punkte:["Interest on debts (account overdrawn)","high: approx. 7–14% p.a."]},rechts:{titel:"Credit interest",punkte:["Interest on credit balances","very low, minus 25% capital gains tax"]}},{type:"merke",text:"Bank statement: credit/+ = balance, debit/− = debt. Charges = all costs for the account (individual or flat fee)."}]},{titel:"Transfer, standing order, direct debit, cash on delivery",blocks:[{type:"begriff",term:"SEPA payment slip",erklaerung:"Form for cashless euro transfers in the SEPA area (EU + UK, Norway, Iceland, Liechtenstein, Switzerland). Same costs as domestic transfers."},{type:"begriff",term:"IBAN & BIC",erklaerung:"IBAN = international account number (AT + check digits + bank code + account number). BIC = the bank's code; not needed for SEPA transfers."},{type:"tabelle",spalten:["","SEPA standing order","SEPA direct debit"],zeilen:[["Payments","regular, same amount","irregular (amount/date changes)"],["Example","Rent, subscription, loan instalment","Electricity, gas, phone"],["Who decides?","the payer","the recipient"],["Order","at the bank","Direct debit mandate to the recipient"],["Cancellation","at the bank","with the recipient"]]},{type:"merke",text:"Advantages of standing orders and direct debits: on time and automatic, no default interest."},{type:"ablauf",titel:"Payment by cash on delivery",schritte:[{titel:"Seller sends the goods by post/courier"},{titel:"Buyer only gets the goods against payment"},{titel:"Delivery person transfers the money to the seller"}]}]},{titel:"Payment cards",blocks:[{type:"tabelle",spalten:["Card","Principle","When is it debited?"],zeilen:[["Debit card","“pay now”","immediately from the account"],["Credit card","“pay later”","collected at the end of the month"],["Prepaid card","“pay before”","credit loaded beforehand, no account needed"]]},{type:"begriff",term:"Debit card",erklaerung:"Cash from ATMs (with PIN), cashless payment in shops and online. Contactless (NFC) up to €50 without PIN."},{type:"begriff",term:"Credit card",erklaerung:"Only with a regular income and from age 18. Pay worldwide, online with card number + expiry date + security code + 3D Secure. Withdrawing cash is expensive!"},{type:"begriff",term:"PIN",erklaerung:"Personal identification number. Never share it, never keep it with the card, cover it when typing. If lost, block the card immediately!"}]},{titel:"E-banking & m-payment",blocks:[{type:"begriff",term:"E-banking (online banking)",erklaerung:"Doing banking over the internet (transfers, standing orders, balance, card settings). Requires a current account, activation and an app."},{type:"begriff",term:"Two-factor authentication",erklaerung:"Each order is confirmed separately: mobile TAN (by SMS) or push TAN (via app)."},{type:"vergleich",links:{titel:"Advantages",punkte:["Any time, anywhere","Up-to-date overview","Few forms","Cheaper"]},rechts:{titel:"Disadvantages",punkte:["No personal contact","Security risks (hackers)","Slow internet"]}},{type:"merke",text:"Banks NEVER send e-mails asking you to enter data (phishing)! Type the address yourself, look for https and the padlock."},{type:"tabelle",spalten:["Online shopping method","How it works"],zeilen:[["Paysafecard","Prepaid card, 16-digit PIN code, no personal data"],["PayPal","Account with PayPal, pay with e-mail + password"],["Klarna","Instant transfer with bank details"],["eps","Transfer with e-banking login directly from the shop"]]},{type:"begriff",term:"M-payment (mobile payment)",erklaerung:"Paying with your phone: hold the phone instead of the card to the till. Via banking apps or systems like Apple Pay, Google Pay."}]}],zusammenfassung:[{titel:"Cash payment",punkte:["Hand over money directly; proof: till receipt, payment note, receipt","Advantages: simple, anonymous, no fees · disadvantages: meeting needed, risk of loss/theft"]},{titel:"Current account",punkte:["Cashless (both have an account) · semi-cash (only one)","Power of disposal (holder) ↔ signing authority; single, either-or, joint account","Debit interest = on debts (high) · credit interest = on balances (low, 25% capital gains tax)","SEPA payment slip: IBAN is enough in the SEPA area","Standing order: regular, same amount, payer decides · direct debit: irregular, recipient debits","Cash on delivery: goods only against payment to the delivery person"]},{titel:"Cards & online",punkte:["Debit card “pay now” · credit card “pay later” · prepaid card “pay before”","Contactless (NFC) up to €50 without PIN","E-banking with two-factor authentication (mobile TAN, push TAN)","Online shopping: Paysafecard, PayPal, Klarna, eps","M-payment = paying with your phone"]}]},"unzuverlaessige-verkaeufer":{schritte:[{titel:"Overview",blocks:[{type:"text",text:"Sometimes a contracting party does not keep to its duties. With sellers there are 3 typical problems:"},{type:"vergleich",links:{titel:"Problems with the seller",punkte:["Late delivery","Delivery of defective products","Incorrect invoice"]},rechts:{titel:"Problems with the buyer",punkte:["Default of acceptance","Default of payment","→ separate topic"]}}]},{titel:"Late delivery",blocks:[{type:"begriff",term:"Late delivery",erklaerung:"The seller does not deliver on time, not in the agreed quality or not at the agreed place."},{type:"entscheidung",titel:"When do the legal consequences apply?",schritte:[{frage:"What kind of delivery date?",links:{antwort:"Exact date / purpose",ergebnis:"Fixed-date transaction",beispiel:"immediately when exceeded"},rechts:{antwort:"Approximate date",weiter:"Ordinary forward transaction"}},{frage:"Reminder with a reasonable extra period (usually 14 days) set?",links:{antwort:"No",ergebnis:"No consequences yet"},rechts:{antwort:"Yes, extra period over",ergebnis:"Legal consequences apply"}}]},{type:"begriff",term:"Buyer's rights",erklaerung:"Withdraw from the contract OR insist on late delivery. In addition, damages if a loss can be proven and the seller is at fault."},{type:"begriff",term:"Substitute purchase",erklaerung:"The buyer buys the goods elsewhere. If they are more expensive, he can claim the difference as damages.",beispiel:"Laptop for €699 didn't arrive → €749 elsewhere → €50 damages"},{type:"merke",text:"With a fixed-date transaction the BUYER must prove that a fixed date was agreed. Read the terms and conditions carefully – they often contain an extra period!"}]},{titel:"Types of defects",blocks:[{type:"begriff",term:"Defect",erklaerung:"The product is faulty, does not match the contract or does not have the features you would normally expect."},{type:"tabelle",spalten:["Classification","Type of defect","Example"],zeilen:[["Visibility","Obvious – visible immediately","Broken glass"],["","Hidden – only shows later","Electronic fault"],["","Fraudulently concealed – seller knew about it","Known fault kept quiet"],["Repairability","Repairable","Loose button"],["","Not repairable","Pane of glass too small"],["Importance","Minor","Different colour than shown"],["","Major","Engine broken"]]},{type:"begriff",term:"Notice of defects",erklaerung:"Telling the seller that there is a defect – as quickly as possible, described exactly and preferably in writing (evidence!)."}]},{titel:"Warranty, guarantee, product liability",blocks:[{type:"tabelle",spalten:["","Warranty (statutory)","Guarantee","Product liability"],zeilen:[["Who is liable?","Seller","Manufacturer or seller","Manufacturer/importer"],["For what?","Defects that were already there at handover","Defects within a period of time","Personal injury and property damage caused by a faulty product"],["Mandatory?","by law","voluntary","by law"],["Regulated in","ABGB, KSchG, UGB, VGG","Contract","PHG (Product Liability Act)"]]},{type:"tabelle",spalten:["Warranty period","Duration"],zeilen:[["New movable items (laptop)","2 years from handover"],["Used movable items","2 years (can be agreed: 1 year)"],["Immovable property (flat)","3 years"],["Fraudulently concealed defects","30 years"]]},{type:"begriff",term:"Reversal of the burden of proof",erklaerung:"At first the SELLER must prove that the product was in order; after that the BUYER must prove that the defect was already there at handover.",beispiel:"B2C (VGG): first 12 months · otherwise (ABGB): first 6 months"},{type:"merke",text:"In B2C the warranty may NOT be excluded. After the period there are still 3 months to go to court (limitation period). Product liability: €500 excess for property damage, applies for up to 10 years."}]},{titel:"Rights in case of defects",blocks:[{type:"ablauf",titel:"Rights under the warranty – in this order",schritte:[{titel:"Improvement (repair) or replacement",text:"Buyer chooses; free of charge for him"},{titel:"Only if that is not possible/refused/takes too long:",text:"Price reduction or cancellation of the contract"}]},{type:"merke",text:"For a minor defect there is only a price reduction, no cancellation of the contract."},{type:"ablauf",titel:"Notice of defects checklist (buyer)",schritte:[{titel:"Refer to the order/delivery note"},{titel:"Confirm receipt"},{titel:"Describe the defect, prove it if possible"},{titel:"Suggest a solution"}]},{type:"begriff",term:"Goodwill",erklaerung:"Voluntary accommodation by the seller beyond his duty (e.g. a discount on the next delivery)."}]},{titel:"Incorrect invoice",blocks:[{type:"tabelle",spalten:["Source of error","Example"],zeilen:[["Prices, reductions, terms different from those agreed","Discount missing, cash discount not stated"],["Calculation error","Wrong total"],["VAT Act requirements not met","VAT ID number missing"]]},{type:"merke",text:"Compare invoices immediately with the offer/order/order confirmation! Only the issuer may correct them (new invoice). If a VAT Act element is missing, there is no input tax deduction."},{type:"ablauf",titel:"Checklist: letter about an incorrect invoice",schritte:[{titel:"Point out the incorrect invoice"},{titel:"Describe and justify the error exactly"},{titel:"Ask for a correction and a new invoice"}]}]}],zusammenfassung:[{titel:"Late delivery",punkte:["Not delivered on time, not in the agreed quality or not at the agreed place","Fixed-date transaction: consequences immediately · ordinary forward transaction: only after a reminder with an extra period","Rights: withdrawal OR late delivery; + damages if at fault (substitute purchase)"]},{titel:"Defects",punkte:["Obvious / hidden / fraudulently concealed · repairable / not repairable · minor / major","Notice of defects as quickly as possible and in writing","Warranty (statutory, seller, defect at handover) · guarantee (voluntary) · product liability (personal/property damage, PHG)","Periods: new 2 yrs · used 2 yrs (1 yr can be agreed) · immovable 3 yrs · fraudulent 30 yrs","Reversal of burden of proof: VGG 12 months · ABGB 6 months","Rights: 1. improvement/replacement → 2. price reduction/cancellation"]},{titel:"Incorrect invoice",punkte:["Sources of error: different terms, calculation errors, VAT Act not met","Only the issuer corrects it; for big errors complain in writing"]}]},"unzuverlaessige-kaeufer":{schritte:[{titel:"Default of acceptance",blocks:[{type:"text",text:"The buyer can also breach his duties: he does not accept the goods (default of acceptance) or does not pay (default of payment)."},{type:"begriff",term:"Default of acceptance",erklaerung:"The buyer does not accept the delivery made according to the contract or does not collect the product."},{type:"merke",text:"The buyer MUST accept if the goods match the order, are free of defects and arrive on time at the agreed place."},{type:"tabelle",spalten:["Seller's right","Applies to","Meaning"],zeilen:[["Deposit","C2C, B2C, B2B","Deposit the goods with the court, ask the buyer to pay"],["Withdrawal","C2C, B2C, B2B","if the buyer still does not pay or both agree"],["Extended deposit","B2B only","Warehouse or similar – at the buyer's expense"],["Self-help sale","B2B only","Auction the goods (after warning); proceeds are credited"]]},{type:"merke",text:"In B2B the buyer must bear all costs (storage, upkeep) and the risk from the default of acceptance onwards."}]},{titel:"Default of payment",blocks:[{type:"begriff",term:"Default of payment",erklaerung:"The buyer does not pay the purchase price at the agreed time. This is the most common breach of duty in a purchase contract."},{type:"vergleich",frage:"Seller's rights:",links:{titel:"Insist on payment",punkte:["Threaten/take legal action","Charge default interest + reminder fees"]},rechts:{titel:"Threaten withdrawal",punkte:["Set an extra period","Then withdraw from the contract"]}},{type:"begriff",term:"Default interest",erklaerung:"Interest the seller can charge from the due date – even if the buyer is not at fault."},{type:"tabelle",spalten:["","Default interest","Reminder fees"],zeilen:[["Regulated in the contract","as agreed","as agreed"],["B2B (UGB)","base rate + 9.2% p.a.","€40 flat fee"],["B2C, C2C (ABGB)","4% p.a.","reasonable amount"]]},{type:"begriff",term:"Calculating default interest",erklaerung:"Interest = capital · interest rate · days / 36,000",beispiel:"€1,000 · 12% · 30 days / 36,000 = €10"}]},{titel:"Dunning process",blocks:[{type:"merke",text:"By law the seller does NOT have to send reminders – he could sue immediately. In practice, however, there is a reminder plan."},{type:"ablauf",titel:"Reminder plan (example)",schritte:[{titel:"Invoice due"},{titel:"1st reminder: payment reminder",text:"polite, without deadline (“Anyone can overlook something”)"},{titel:"2nd reminder",text:"Set a deadline, threaten default interest and reminder fees"},{titel:"3rd reminder (final, registered mail)",text:"Charge interest + fees, threaten further steps"},{titel:"Lawyer or debt collection agency"},{titel:"Court payment order procedure, seizure"}]},{type:"begriff",term:"Debt collection agency & seizure",erklaerung:"Debt collection agency = company that collects debts. Seizure = wages, account or items are seized to pay the debts."},{type:"ablauf",titel:"Court payment order procedure (up to €75,000)",schritte:[{titel:"Seller sues for the outstanding amount"},{titel:"Court issues a conditional payment order",text:"pay within 14 days or object within 4 weeks"},{titel:"Objection?",text:"Yes → civil proceedings (court hearing)"},{titel:"No objection, no payment",text:"Payment order becomes final"},{titel:"Still no payment",text:"→ seizure"}]},{type:"ablauf",titel:"Reminder letter checklist",schritte:[{titel:"Subject: payment reminder / reminder / final reminder"},{titel:"Refer to the overdue invoice"},{titel:"Request payment, set a deadline"},{titel:"Announce/charge default interest and reminder fees"},{titel:"Possibly threaten legal consequences"}]}]}],zusammenfassung:[{titel:"Default of acceptance",punkte:["Buyer does not accept/collect the delivery made according to the contract","Rights: deposit with the court, withdrawal · B2B only: extended deposit, self-help sale","B2B: buyer bears costs and risk"]},{titel:"Default of payment",punkte:["Buyer does not pay on time","Rights: insist on payment (+ default interest, reminder fees) or withdrawal after an extra period","B2B: base rate + 9.2% p.a., €40 flat fee · B2C/C2C: 4% p.a.","Interest = capital · interest rate · days / 36,000"]},{titel:"Dunning process",punkte:["Reminders not compulsory; reminder plan: payment reminder → reminder → final reminder (registered) → lawyer/debt collection","Court payment order procedure up to €75,000: conditional payment order → objection (trial) or final → seizure"]}]},rechtsdurchsetzung:{schritte:[{titel:"Enforcing your rights",blocks:[{type:"text",text:"Sometimes even a lot of communication does not help. Then you have to think about how best to enforce your rights."},{type:"ablauf",titel:"Enforcing your own rights",schritte:[{titel:"Clarify your own interest: What do I want?",text:"decide concretely what you can demand"},{titel:"Notify the contracting partner: What do I want by when?",text:"demand with an exact deadline, preferably by registered mail"},{titel:"Weigh it up: Is a legal dispute worth it?"},{titel:"Advice: What do experts say?",text:"lawyer or advice centre"},{titel:"Decision: out-of-court settlement or court case?"}]}]},{titel:"Disadvantages of a legal dispute",blocks:[{type:"begriff",term:"Court",erklaerung:"Its task is to settle legal conflicts and pass judgements."},{type:"tabelle",spalten:["Disadvantage","Why?"],zeilen:[["Lengthy","Court cases often take a very long time"],["Uncertain","you never know for sure how it will end"],["Expensive","lawyer, court – the loser pays ALL costs, including the winner's"],["Damaging to reputation","usually the end of the business relationship with an important stakeholder"]]},{type:"begriff",term:"Burden of proof",erklaerung:"Whoever claims something must prove it. Whoever has to prove it is at a disadvantage in a dispute.",beispiel:"Claiming a fixed-date transaction? → the buyer must prove it."}]},{titel:"Alternatives to court",blocks:[{type:"tabelle",spalten:["Alternative","How it works","Binding?"],zeilen:[["Goodwill","both sides voluntarily meet halfway","–"],["Mediation","a neutral mediator helps to find a solution","no"],["Conciliation body","gives recommendations for a solution","no"],["Arbitration tribunal","private court, agreed in the contract","YES"]]},{type:"merke",text:"Only the arbitration tribunal's decision is legally binding – conciliation bodies only give recommendations."}]}],zusammenfassung:[{titel:"Procedure",punkte:["Clarify interest → notify partner (with deadline) → weigh up → get advice → decide"]},{titel:"Court",punkte:["The court settles legal conflicts and passes judgements","Disadvantages: lengthy, uncertain, expensive (loser pays everything), damaging to reputation","Burden of proof: whoever has to prove is at a disadvantage"]},{titel:"Alternatives",punkte:["Goodwill (voluntary) · mediation (neutral mediator) · conciliation body (recommendation, not binding) · arbitration tribunal (binding)"]}]},"unternehmensgruendung-schritte":{schritte:[{titel:"The path to your own company",blocks:[{type:"ablauf",titel:"Steps to starting a business",schritte:[{titel:"Will to start a business + business idea"},{titel:"Check the founder",text:"personal and trade law requirements"},{titel:"Choose the legal form"},{titel:"Write a business plan"}]},{type:"begriff",term:"Will to start a business",erklaerung:"The wish to open your own company or put an idea into practice."},{type:"vergleich",links:{titel:"Self-employed",punkte:["Own trade business","Agriculture/forestry","Liberal profession (doctor, lawyer)","New self-employed (artists)"]},rechts:{titel:"Employed",punkte:["Employee in an employment relationship"]}},{type:"vergleich",frage:"Self-employment:",links:{titel:"Advantages",punkte:["Self-determination","“Being your own boss”","High motivation","The profit is mine","Free choice of working hours"]},rechts:{titel:"Disadvantages",punkte:["No secure job","Financial risk","High pressure to perform","Liability with private assets","A lot of time required"]}}]},{titel:"Business idea",blocks:[{type:"vergleich",frage:"Ways to a business idea:",links:{titel:"New start-up",punkte:["Develop a new idea","Improve/develop proven ideas"]},rechts:{titel:"Use an existing idea",punkte:["Business takeover","Franchising"]}},{type:"tabelle",spalten:["","Advantages","Disadvantages"],zeilen:[["Business takeover","less investment, established processes, existing customers & suppliers","defects are taken over, structures hard to change"],["Franchising","proven concept, well-known brand, support","fees, little room for own ideas"]]},{type:"begriff",term:"Franchising",erklaerung:"The franchisor provides a tested concept for a fee; the franchisee implements it independently.",beispiel:"McDonald's, Subway"},{type:"ablauf",titel:"A good business idea …",schritte:[{titel:"… convinces customers",text:"brings advantages (faster, safer, easier)"},{titel:"… is better than the competition",text:"USP = unique selling proposition"},{titel:"… has a chance on the market"},{titel:"… can be financed"},{titel:"… is profitable"}]}]},{titel:"Entrepreneur & company name",blocks:[{type:"begriff",term:"Entrepreneur (UGB)",erklaerung:"Someone who runs a business. Business = permanent organisation with independent economic activity – even if it is not aimed at profit."},{type:"begriff",term:"Company name (Firma)",erklaerung:"The name entered in the company register under which the entrepreneur does business, signs, and can sue or be sued."},{type:"kette",glieder:[{titel:"freely chosen",wert:"Core name"},{titel:"Legal form",wert:"+ legal form suffix"},{titel:"e.g.",wert:"Lisa Berger e. U."}]},{type:"merke",text:"Not entered in the company register? Then there is no company name, only a business designation (first name and surname)."}]},{titel:"Requirements for starting a business",blocks:[{type:"tabelle",spalten:["Personal requirements","Examples"],zeilen:[["Personal qualities","Personal responsibility, willingness to take risks, creativity, resilience to stress"],["Professional qualifications","Expertise, industry experience, business knowledge"],["Personal environment","Support from family/partner"]]},{type:"begriff",term:"Trade licence",erklaerung:"Permission for a trade activity, issued by the trade authority (district authority/municipal authority)."},{type:"begriff",term:"Trade activity",erklaerung:"Permitted + independent + regular + for payment (intention to make a profit)."},{type:"begriff",term:"General requirements",erklaerung:"At least 18 years old · Austrian, EU/EEA or Swiss citizenship · no grounds for exclusion (e.g. conviction, insolvency)."},{type:"tabelle",spalten:["Type of trade","Requirements","Examples"],zeilen:[["Free trade","general","Advertising agency, photographer, gym"],["Regulated","+ certificate of competence","Baker, hairdresser, hospitality"],["Regulated with reliability check","+ certificate of competence + reliability check","Master builder, travel agency, pyrotechnician"]]},{type:"merke",text:"Certificate of competence = proof of professional knowledge (e.g. master craftsman exam, HAK + practice). Liberal professions and new self-employed do not need a trade licence."}]}],zusammenfassung:[{titel:"Starting a business",punkte:["Will to start + business idea → requirements → legal form → business plan","Self-employed (trade, liberal profession) ↔ employed (employee)","Business idea: new start-up or use an existing one (takeover, franchising)","Good idea: convinces customers, better than the competition (USP), market chance, financeable, profitable"]},{titel:"Entrepreneur & company name",punkte:["Business = permanent, independent economic organisation","Company name = name in the company register = core name + legal form suffix"]},{titel:"Requirements",punkte:["Personal: qualities, expertise, environment","Trade activity = permitted, independent, regular, for payment","General: 18 years, citizenship (AT/EU/EEA/CH), no grounds for exclusion","Free trades · regulated (+ certificate of competence) · with reliability check"]}]},"wahl-der-rechtsform-1jg":{schritte:[{titel:"Criteria for the legal form",blocks:[{type:"begriff",term:"Legal form",erklaerung:"The legal “shell” of a company. It regulates e.g. who is liable and who decides."},{type:"tabelle",spalten:["Criterion","Question"],zeilen:[["Number of owners","Start alone or with partners?"],["Raising capital","Is minimum capital required?"],["Liability","Who is liable for debts, and how much?"],["Management/control","Who runs the business?"],["Distribution of profit","Who gets the profit, who bears the loss?"],["Type of bookkeeping","Cash-based accounting or double-entry bookkeeping?"]]},{type:"tabelle",spalten:["Group","Examples"],zeilen:[["Sole proprietorship","1 person = sole owner"],["Partnerships","OG, KG"],["Corporations","GmbH, AG"],["Special forms","Cooperative"]]}]},{titel:"The sole proprietorship",blocks:[{type:"begriff",term:"Sole proprietorship",erklaerung:"The entrepreneur is the sole owner – all the rights, but also all the duties. The most common legal form in Austria; it is created when the trade is registered."},{type:"tabelle",spalten:["Criterion","Rule for a sole proprietorship"],zeilen:[["Owner","The sole proprietor owns 100%"],["Capital","raised by the owner (equity + borrowed capital); NO minimum capital"],["Liability","Fully liable: personally and without limit – including private assets"],["Management","decides alone"],["Profit","profit alone, loss alone"],["Bookkeeping","Cash-based accounting; from €1 million turnover (or 2 years at €700,000 each) double-entry bookkeeping"]]},{type:"vergleich",links:{titel:"Advantages",punkte:["Quick, simple set-up","No minimum capital","Profit does not have to be shared"]},rechts:{titel:"Disadvantages",punkte:["High risk (private assets)","A lot of responsibility","No one to stand in during illness"]}},{type:"merke",text:"Above the turnover limits the sole proprietor must register in the company register → “registered entrepreneur (e. U.)”. This can also be done voluntarily earlier."}]}],zusammenfassung:[{titel:"Legal form",punkte:["Criteria: owners, capital, liability, management, distribution of profit, bookkeeping","Sole proprietorship · partnerships (OG, KG) · corporations (GmbH, AG) · special forms (cooperative)"]},{titel:"Sole proprietorship",punkte:["Sole owner, created by registering the trade, no minimum capital","Personally liable without limit (fully liable)","Decides alone, profit/loss alone","Cash-based accounting; from €1 million turnover double-entry bookkeeping + company register (e. U.)","+ simple, no minimum capital · − high risk, no one to stand in"]}]},"businessplan-1jg":{schritte:[{titel:"What is a business plan?",blocks:[{type:"begriff",term:"Business plan",erklaerung:"Written document in which the founder presents the business idea and describes how it is to be put into practice."},{type:"merke",text:"A well-thought-out business plan increases the chances of success. Anyone who wants a bank loan or funding MUST submit one."},{type:"tabelle",spalten:["Function","Meaning"],zeilen:[["Assessing","Is the idea feasible, economical, with enough customer benefit?"],["Convincing","Convincing customers, suppliers, investors, funding bodies"],["Planning","Planning the implementation in a targeted way"],["Steering","Steering the start-up phase, checking goals"]]}]},{titel:"Components",blocks:[{type:"ablauf",titel:"Business plan checklist",schritte:[{titel:"Executive summary",text:"Overview of the most important statements and key figures"},{titel:"Company",text:"Profile, activity, people, legal form"},{titel:"Product and service"},{titel:"Industry, market and competition",text:"Sales volume, trends, competitors"},{titel:"Marketing",text:"Prices, advertising, sales channels"},{titel:"Opportunities and risks"},{titel:"Financial planning",text:"Capital requirements, financing, turnover"},{titel:"Implementation roadmap",text:"Milestones with dates"}]},{type:"begriff",term:"Margin",erklaerung:"Profit margin – amount left over as profit from a sale."},{type:"begriff",term:"Overdraft facility",erklaerung:"Overdraft limit on the current account – for short-term cash shortages."}]}],zusammenfassung:[{titel:"Business plan",punkte:["Written presentation of the business idea and how it will be implemented","Functions: assessing, convincing, planning, steering","Required for a bank loan and funding","Components: executive summary, company, product, industry/market/competition, marketing, opportunities/risks, financial planning, implementation roadmap"]}]},"vertraege-mitarbeiter":{schritte:[{titel:"Types of employment",blocks:[{type:"text",text:"When a company employs people, there are 3 types of contract with different rights and duties:"},{type:"tabelle",spalten:["","“Genuine” employment contract","Freelance service contract","Contract for work"],zeilen:[["What is owed?","personal labour","labour, but without personal dependence","a result / a piece of work"],["Bound by instructions?","yes","no","no"],["Fixed working hours & place?","yes","no","no"],["Can someone else stand in?","no, personally","yes","yes (own employees)"],["Work equipment","from the employer","usually from the client","own"],["Economic risk","Employer","Client","The contractor himself"],["Example","Salaried employees, workers, apprentices","Data entry from home","Designing a website for €7,000"]]},{type:"merke",text:"With a contract for work, you only get money when the work is finished as agreed – and you are liable for faults (warranty)."},{type:"entscheidung",titel:"Which contract is it?",schritte:[{frage:"Is a finished piece of work/result owed?",links:{antwort:"Yes",ergebnis:"Contract for work"},rechts:{antwort:"No, labour",weiter:"keep checking"}},{frage:"Bound by instructions, working hours and place?",links:{antwort:"No",ergebnis:"Freelance service contract"},rechts:{antwort:"Yes",ergebnis:"“Genuine” employment contract"}}]}]},{titel:"Statement of employment terms (Dienstzettel)",blocks:[{type:"begriff",term:"Statement of employment terms",erklaerung:"Written record of the most important rights and duties from the employment relationship."},{type:"merke",text:"An employment contract has no set form. If there is no written contract, the employer MUST issue a statement of employment terms immediately. Exceptions: employment max. 1 month or a written contract with all details."},{type:"ablauf",titel:"Contents of a statement of employment terms",schritte:[{titel:"Name and address of employer and employee"},{titel:"Start (for fixed-term also end) and probationary period"},{titel:"Collective agreement, grade"},{titel:"Notice periods and dates"},{titel:"Usual place of work"},{titel:"Amount and due date of pay, special payments"},{titel:"Holiday entitlement"},{titel:"Normal working hours"},{titel:"Employee provision fund"}]},{type:"begriff",term:"Fixed-term employment",erklaerung:"Only for a certain period of time.",beispiel:"Winter season in tourism"}]}],zusammenfassung:[{titel:"Types of employment",punkte:["“Genuine” employment contract: personal labour, bound by instructions, fixed time/place, work equipment from the employer, no risk","Freelance service contract: labour without personal dependence, free choice of time/place, someone else can stand in","Contract for work: owes a result/work, own equipment, own risk, warranty; money only on completion"]},{titel:"Statement of employment terms",punkte:["Written record of the essential rights and duties","Mandatory if there is no written employment contract (unless duration ≤ 1 month)","Content: parties, start/end, probation, collective agreement & grade, notice, place of work, pay, holiday, working hours, provision fund"]}]}},questions:{"grundlagen-des-wirtschaftens":[{question:'What is meant by a "need"?',options:["The wish to remove a felt lack","A good that can be bought on the market","A means of reaching a goal with as little input as possible","The state of a company without profit"],explanation:"A need is a subjectively felt lack, combined with the wish to remove it.",correctIndex:0},{question:"To make chocolates in Loopy's Candy Store, Loopy uses tap water, which she does not pay for. What type of good is it?",options:["Free good","Economic good","Capital good","Service"],explanation:"Free goods are available in unlimited amounts and cost nothing (e.g. air, tap water). Economic goods, on the other hand, are scarce and must be paid for.",correctIndex:0},{question:"Loopy buys a new chocolate moulding machine for Loopy's Candy Store. What type of good is it?",options:["Consumer good","Capital good","Free good","Service"],explanation:"Capital goods are used by companies to produce other goods (here: the machine for chocolate production). Consumer goods, by contrast, are used directly by private households.",correctIndex:1},{question:"A customer buys a bag of sweets in Loopy's Candy Store to eat right away. What type of good is it for the customer?",options:["Capital good","Consumer good","Free good","Means of production"],explanation:"Goods that private households use to satisfy their needs directly are called consumer goods.",correctIndex:1},{question:"For the Christmas season Loopy has a budget of exactly 200 euros and wants to buy as much packaging for her chocolates as possible. Which principle is she following?",options:["Maximum principle","Minimum principle","Principle of sustainability","Principle of equivalence"],explanation:"With the maximum principle, the greatest possible result is aimed for with a given (fixed) input. With the minimum principle it is the other way round: a fixed goal is reached with as little input as possible.",correctIndex:0},{question:"Loopy wants exactly 500 chocolate boxes made for her Candy Store and is looking for the cheapest supplier. Which principle is she following?",options:["Maximum principle","Minimum principle","Economic system","Principle of needs"],explanation:"With the minimum principle the goal is fixed (here: 500 boxes) and the smallest possible input is sought. Together with the maximum principle it forms the economic principle.",correctIndex:1},{question:"Which of the following is NOT one of the four classic economic participants in the complete circular flow?",options:["Companies","Private households","Banks","Clubs and associations"],explanation:"The four economic participants in the complete circular flow are companies, private households, the state and banks. Clubs are not one of them.",correctIndex:3},{question:"Loopy's Candy Store supplies chocolates to private households. What does the company receive from the households in return?",options:["Labour (work performed)","Taxes (levies)","Money (purchase price)","Loans (credit)"],explanation:"Between companies and private households, goods and services flow in one direction, and money (the purchase price) flows in the other direction in return.",correctIndex:2}],"der-markt":[{question:"Instead of growing, roasting AND processing cocoa herself, Loopy buys ready-made cocoa and concentrates only on making chocolates in Loopy's Candy Store. What is this specialisation in individual production steps called?",options:["Division of labour","Market equilibrium","Planned economy","Satisfaction of needs"],explanation:"With division of labour, people or companies specialise in certain tasks or production steps instead of doing everything themselves.",correctIndex:0},{question:"In Loopy's Candy Store each employee is responsible for a different step: one shapes the chocolates, one packs them, one sells them in the shop. What type of division of labour is this?",options:["Division of labour between companies","Division of labour within the company","International division of labour","National division of labour"],explanation:"When individual work steps within one company are split among different employees, this is called division of labour within the company.",correctIndex:1},{question:"Loopy gets her cocoa from a supplier in Ecuador and her packaging from a manufacturer in Italy. What type of division of labour is this?",options:["Division of labour within the company","National division of labour","International division of labour","Horizontal division of labour"],explanation:"If the division of labour extends across a country's borders, it is called international division of labour.",correctIndex:2},{question:"Which economic sector does Loopy's Candy Store belong to, since it processes raw materials into finished chocolates?",options:["Primary sector","Secondary sector","Tertiary sector","Quaternary sector"],explanation:"The secondary sector (production/industry) processes raw materials into finished goods. The primary sector extracts raw materials (primary production), the tertiary sector covers services.",correctIndex:1},{question:"On which market does Loopy act as a supplier when she sells her chocolates to customers?",options:["Labour market","Investment goods market","Consumer goods market","Procurement market"],explanation:"Finished goods that private households consume – such as chocolates – are traded on the consumer goods market.",correctIndex:2},{question:"In Loopy's town there is only one supplier of handmade chocolates: Loopy's Candy Store. What is this market form called?",options:["Polypoly","Oligopoly","Monopoly","Free market economy"],explanation:"If there is only one supplier on a market, it is called a monopoly (supply monopoly).",correctIndex:2},{question:"What does the law of supply say?",options:["If the price of a good rises, supply falls","If the price of a good rises, supply rises","If the price of a good rises, supply stays the same","Supply does not depend on the price"],explanation:"According to the law of supply: if the price of a good rises, the supply of this good also rises, because suppliers want to sell more of it.",correctIndex:1},{question:"What does the law of demand say?",options:["If the price of a good rises, demand rises","If the price of a good rises, demand falls","Demand does not depend on the price","If the price falls, demand also falls"],explanation:"According to the law of demand: if the price of a good rises, demand for it falls (and vice versa).",correctIndex:1},{question:"At which point is the market price (equilibrium price) formed?",options:["Where the quantity supplied is highest","Where the quantity demanded is highest","Where the supply and demand curves intersect","Where the price is set officially by the state"],explanation:"The market price (equilibrium price) is formed where the supply and demand curves intersect, i.e. where the quantity supplied equals the quantity demanded (market equilibrium).",correctIndex:2},{question:"In which economic system does the state decide centrally what is produced, how much and for whom, instead of letting supply and demand work freely?",options:["Free market economy","Social market economy","Planned economy","Oligopoly"],explanation:"In a planned economy the state plans and steers centrally what is produced, how much and for whom.",correctIndex:2}],"unternehmen-und-umfeld":[{question:'What is meant by the term "establishment" (Betrieb)?',options:["The legal framework for producing goods and services","The place where goods or services are provided","The name of a company entered in the company register","A group of a company's customers"],explanation:"The establishment is the place where goods or services are actually produced. An enterprise can have several establishments.",correctIndex:1},{question:`Loopy's Candy Store is entered in the company register under the name "Loopys Candy Store e.U.". Which term is this?`,options:["Establishment (Betrieb)","Enterprise (Unternehmen)","Company name (Firma)","Branch (Filiale)"],explanation:"The company name (Firma) is the name of an enterprise entered in the company register, under which it operates on the market.",correctIndex:2},{question:"Loopy makes handmade chocolates from cocoa in her small kitchen workshop. Which type of business is Loopy's Candy Store according to its output?",options:["Primary sector business","Secondary sector business","Tertiary sector business","Quaternary sector business"],explanation:"Since Loopy processes raw materials (e.g. cocoa) into finished chocolates, her business belongs to the secondary sector (manufacturing business).",correctIndex:1},{question:"With only 4 employees, which business size does Loopy's Candy Store belong to according to EU criteria?",options:["Micro business","Small business","Medium-sized business","Large business"],explanation:"According to the EU definition, micro businesses employ up to 9 people. Loopy's Candy Store with 4 employees is therefore a micro business.",correctIndex:0},{question:"This year Loopy wants to produce and sell exactly 50,000 boxes of chocolates. What type of company goal is this?",options:["Formal goal","Material goal","Stakeholder goal","Ecological environment"],explanation:"Material goals describe what a company concretely does – i.e. which goods or services are to be provided (here: the quantity of chocolates produced).",correctIndex:1},{question:"Loopy sets the goal of increasing the profit of Loopy's Candy Store by 10% next year. What type of formal goal is this?",options:["Monetary formal goal","Non-monetary formal goal","Material goal","Ecological goal"],explanation:"Monetary formal goals can be measured in money – like the increase in profit here. Non-monetary goals (e.g. customer satisfaction) cannot be expressed in money.",correctIndex:0},{question:"Which group of stakeholders do the employees of Loopy's Candy Store belong to?",options:["External stakeholders","Internal stakeholders","Competitors","Society"],explanation:"A company's internal stakeholders include owners, management and employees. Customers, suppliers or the state, on the other hand, are external stakeholders.",correctIndex:1},{question:"The cocoa farmer from whom Loopy buys her cocoa belongs to which group of stakeholders of Loopy's Candy Store?",options:["Internal stakeholder","External stakeholder","Management","Owner"],explanation:"Suppliers are external stakeholders of a company because they are outside the company but have an interest in its business.",correctIndex:1},{question:"Rising world market prices for cocoa affect Loopy's Candy Store. Which of the company's environments does this belong to?",options:["Economic environment","Social environment","Technological environment","Ecological environment"],explanation:"The economic environment describes the economic conditions on national and international markets, such as raw material prices.",correctIndex:0}],"leistungserstellung-1jg":[{question:"Loopy's chocolate moulding machine belongs to which factor of production?",options:["Human labour","Fixed assets","Current assets","Financial current assets"],explanation:"Machines are (tangible) fixed assets, because they are used in the company over a long period.",correctIndex:1},{question:"The stock of cocoa that Loopy keeps in her warehouse for the next production run belongs to which factor of production?",options:["Fixed assets","Current assets","Human labour","Intangible fixed assets"],explanation:"Raw materials such as cocoa are tangible current assets, because they only stay in the business for a short time and are used up in the production process.",correctIndex:1},{question:"Which basic functional area does it belong to when Loopy orders new cocoa beans from her supplier?",options:["Production","Sales","Procurement","Human resources"],explanation:"Procurement ensures that the company is supplied with the necessary materials – here the cocoa.",correctIndex:2},{question:"When Loopy sells her finished chocolates to customers in the shop, which area does this belong to?",options:["Procurement (purchasing)","Production (manufacturing)","Sales (distribution)","Warehouse (storage)"],explanation:"Sales (distribution) covers selling the goods or services on the market.",correctIndex:2},{question:"Loopy hires a new employee and takes care of her employment contract and induction. Which area does this belong to?",options:["Accounting","Human resources","Warehouse","Corporate management"],explanation:"Human resources covers all tasks related to employees, e.g. recruiting and looking after them during their employment.",correctIndex:1},{question:"Loopy records all income and expenses of Loopy's Candy Store in figures. Which area does this activity belong to?",options:["Accounting","Management","Sales","Warehouse"],explanation:"Accounting is used to record all business processes in figures, e.g. income and expenses.",correctIndex:0},{question:"Loopy plans the goals of Loopy's Candy Store for next year, makes decisions on how to implement them and regularly checks the success. Which area does this belong to?",options:["Warehousing","Human resources","Management","Accounting"],explanation:"Management covers setting goals/planning, deciding, organising/steering and controlling.",correctIndex:2},{question:"Why does Loopy run a warehouse for packaging material and finished chocolates?",options:["So that the necessary goods are available on time","To save taxes through high stock levels","So that fewer staff are needed in production","Because the UGB requires every business to have a warehouse"],explanation:"The task of the warehouse is to make sure the necessary goods are available at the right time in the business process.",correctIndex:0}],"phasen-kaufen-verkaufen":[{question:"Into which three phases can a purchase contract be divided?",options:["Advertising, sales pitch, guarantee","Initiation, conclusion, fulfilment","Enquiry, delivery, complaint","Offer, invoice, withdrawal"],explanation:"Every purchase goes through the three phases of initiation, conclusion and fulfilment of the purchase contract.",correctIndex:1},{question:`Loopy puts a poster saying "Advent calendar – while stocks last!" in the shop window of Loopy's Candy Store. What is this legally?`,options:["A binding offer","An advertisement","An order","A purchase contract"],explanation:'Advertising boards, brochures or shop window posters with notes like "while stocks last" are legally non-binding advertisements – the seller does not yet take on any obligation.',correctIndex:1},{question:'A customer writes Loopy an e-mail: "Could you please send me your current chocolate catalogue with prices?" What is this?',options:["A binding offer","An enquiry","An order","An advertisement"],explanation:"An enquiry is legally non-binding – the customer only asks for information without taking on any obligation.",correctIndex:1},{question:"Which five elements must an offer contain to be legally binding?",options:["Advertising, price, quantity discount, delivery time, guarantee","Specific buyer and seller, quality, quantity, price","Company name, address, phone number, e-mail address, VAT number","Initiation, conclusion, fulfilment, delivery, payment"],explanation:"A binding offer must clearly specify the seller, buyer, quality, quantity and price of the product.",correctIndex:1},{question:'Loopy always adds "prices subject to change" to the offers in her online shop. What does this wording do?',options:["It makes the offer legally binding for both sides","As an exemption clause it frees Loopy from being bound by the offer","It extends the customers' withdrawal period from 14 to 30 days","It obliges Loopy to announce any price change in writing in advance"],explanation:'With an exemption clause (e.g. "prices subject to change", "without obligation") the seller can free himself from being bound by his offer – this is called an offer without obligation.',correctIndex:1},{question:"A customer accepts Loopy's binding offer unchanged and on time. What happens as a result?",options:["Only a non-binding enquiry from the customer is created","The purchase contract is concluded through mutual declaration of intent","The purchase contract only comes into being on delivery of the goods","Loopy can still freely withdraw the offer until the goods have been delivered"],explanation:"By accepting a binding offer on time and unchanged, the purchase contract is concluded through the mutual declaration of intent of buyer and seller.",correctIndex:1},{question:"Which two duties does Loopy have as the seller when a purchase contract is fulfilled?",options:["Placing ads and granting a quantity discount","Delivering the goods and issuing the invoice","Accepting the goods and paying the purchase price","Answering an enquiry and creating a binding offer"],explanation:"When fulfilling the purchase contract, the seller must deliver the goods and issue a proper invoice. In return, the buyer must accept and pay for the goods.",correctIndex:1},{question:"At what age do you have full legal capacity in Austria and can therefore conclude any purchase contract on your own?",options:["From 14","From 16","From 18","From 21"],explanation:"On your 18th birthday you gain full legal capacity in Austria and can conclude all contracts on your own.",correctIndex:2},{question:"A 15-year-old customer buys a bag of sweets for 3 euros from Loopy with his pocket money. How is his legal capacity classified at this age?",options:["No legal capacity (child under 7)","Immature minor (only limited legal capacity)","Mature minor (extended limited legal capacity)","Mature minor (already full legal capacity)"],explanation:"Between 14 and 18 you are a mature minor with extended limited legal capacity – e.g. you may make smaller purchases yourself with your own income such as pocket money.",correctIndex:2}],"gesetzliche-grundlagen-kauf":[{question:"Loopy (a business owner) sells chocolates to a private customer. What type of business is this?",options:["C2C","B2C","B2B","G2C"],explanation:"When a company sells to a private person, it is called a B2C deal (business-to-consumer).",correctIndex:1},{question:"Loopy buys large amounts of flour from an industrial bakery for her chocolate production. What type of business is this?",options:["C2C","B2C","B2B","B2G"],explanation:"When two companies trade with each other, it is called a B2B deal (business-to-business).",correctIndex:2},{question:"Which law specifically protects private persons (consumers) from unfair contract terms in deals with companies?",options:["UGB","KSchG","ECG","GDPR"],explanation:"The Consumer Protection Act (KSchG) protects private persons from unfair practices and inadmissible contract terms in dealings with companies.",correctIndex:1},{question:"Which law applies in principle to all contracts, regardless of who the contracting parties are?",options:["UGB","ECG","ABGB","FAGG"],explanation:"The Austrian Civil Code (ABGB) applies to all contracts regardless of the contracting parties, e.g. for the rules on legal capacity.",correctIndex:2},{question:"Loopy opens an online shop for her chocolates. Which law must she pay particular attention to, because it regulates information duties on websites?",options:["UGB (Austrian Commercial Code)","ECG (E-Commerce Act)","KSchG","ABGB (Austrian Civil Code)"],explanation:"The E-Commerce Act (ECG) applies to all sales made through an online shop and regulates e.g. information duties on the website.",correctIndex:1},{question:"Which law specifically regulates contracts concluded outside a company's business premises (e.g. doorstep sales)?",options:["FAGG (Distance and Off-Premises Contracts Act)","ABGB (Austrian Civil Code)","GDPR (General Data Protection Regulation)","ECG (E-Commerce Act)"],explanation:"The FAGG applies to deals between companies and private persons that are concluded outside the company's business premises, e.g. doorstep sales.",correctIndex:0},{question:"Loopy collects her customers' e-mail addresses for her newsletter. Which law regulates the handling of this personal data?",options:["UGB","KSchG","GDPR","ABGB"],explanation:"The General Data Protection Regulation (GDPR) regulates the handling of personal data in the EU and requires, for example, that users consent to the use of their data.",correctIndex:2},{question:"Which law applies specifically to contracts between two companies?",options:["KSchG (Consumer Protection Act)","UGB (Austrian Commercial Code)","FAGG (Distance and Off-Premises Contracts Act)","ECG"],explanation:"The Austrian Commercial Code (UGB) applies to contracts between companies (B2B deals).",correctIndex:1},{question:"A tradesman repairs the shop lighting for Loopy in return for payment. What type of contract is this (not a purchase contract)?",options:["Rental contract","Contract for work","Employment contract","Loan agreement"],explanation:'With a contract for work, a specific result (a "work", e.g. a repair) is provided in return for payment.',correctIndex:1}],"fernabsatz-ecommerce":[{question:"A customer orders chocolates via Loopy's online shop without being in the shop in person. What is this way of concluding a contract called?",options:["In-person transaction","Distance selling","Doorstep sale","Handshake deal"],explanation:"Distance selling means that the contracting parties do not meet in person when concluding the purchase contract and only use means of distance communication.",correctIndex:1},{question:"What is a contract concluded specifically over the internet called?",options:["Distance selling","E-commerce","Direct sales","B2B trade"],explanation:"If the contract is concluded over the internet, it is called electronic commerce or e-commerce.",correctIndex:1},{question:"Which of the following does Loopy NOT have to state in her online shop by law?",options:["Name and address of the company","Total price including taxes","The owner's favourite colour","Information on the right of withdrawal"],explanation:"Sellers in e-commerce must state e.g. name, address, total price and right of withdrawal – personal preferences such as a favourite colour are not part of the legal duty to inform.",correctIndex:2},{question:"In which order does a typical purchase in Loopy's online shop take place?",options:["Click the order button → put the product in the basket → enter details and payment method","Put the product in the basket → enter details and payment method → click the order button","Enter details and payment method → receive the invoice → put the product in the basket","Pay → put the product in the basket → click the order button"],explanation:"Concluding a contract online typically works like this: put products in the basket, give personal details and payment method, then trigger the purchase with the order button.",correctIndex:1},{question:"Which statement about legal protection when shopping online is true?",options:["The internet is a lawless space in which no laws apply","Legal protection rules such as the KSchG, FAGG and ECG apply","Only companies, not consumers, are legally protected when shopping online","Online purchases are generally non-binding until delivery"],explanation:"Legal protection rules (e.g. KSchG, FAGG, ECG) also apply to online shopping – the internet is not a lawless space.",correctIndex:1},{question:"What can a qualified electronic signature with the ID Austria be used for in Austria?",options:["Only for paying bills in online banking","As a legally equal replacement for a handwritten signature","Only for official procedures like FinanzOnline, not for contracts","It replaces a signature only for contracts up to 1,000 euros"],explanation:"In Austria the qualified electronic signature (e.g. with the ID Austria) is legally equivalent to a handwritten signature.",correctIndex:1},{question:"Which of the following is NOT one of the classic means of distance communication for a distance contract?",options:["Ordering by phone","Order form from a mail-order catalogue","Personal conversation in the shop","Ordering by e-mail"],explanation:"Means of distance communication are e.g. internet, phone, e-mail, catalogue or letter. A personal conversation in the shop, on the other hand, is an in-person sale, not distance selling.",correctIndex:2},{question:"Why should you look for quality seals and a legal notice on the website when shopping online?",options:["Because quality seals guarantee a discount on the order","To better judge how reputable the online retailer is","Because a legal notice legally caps the shipping costs","Because both legally extend the withdrawal period to 30 days"],explanation:"Quality seals and a complete legal notice help to tell reputable online retailers from dubious ones and to prevent fraud.",correctIndex:1}],ruecktrittsrechte:[{question:"Once a purchase contract has been validly concluded, the buyer can in principle …",options:["withdraw at any time without giving a reason","no longer simply undo the contract","renegotiate the price afterwards","always exchange the goods free of charge"],explanation:'Once a purchase contract has been validly concluded, there is in principle no simple way "back" – buyer and seller must fulfil the contract.',correctIndex:1},{question:"A customer simply wants to exchange a box of chocolates bought in Loopy's shop because she has changed her mind. What is she entitled to by law?",options:["A statutory right to exchange the goods within 14 calendar days","Nothing, a right to exchange has to be agreed separately","An automatic refund of the full purchase price","A statutory credit note for the purchase price"],explanation:"In Austria there is no legal right to exchange items bought in a shop – it is up to the seller whether to offer an exchange or a credit note as a goodwill gesture.",correctIndex:1},{question:"Under which condition can a buyer withdraw from a valid purchase contract?",options:["Always, even without a particular reason","If the seller has fraudulently deceived him","Only if the purchase price is over 100 euros","Only for purchases directly in the seller's shop"],explanation:"Withdrawal is possible e.g. if a right of withdrawal was agreed, the contract was concluded unlawfully, there was fraudulent deception, or the seller is in default with fulfilment.",correctIndex:1},{question:"For which type of deals do the special rights of withdrawal for consumers apply (e.g. under the FAGG)?",options:["Only for deals in a shop, but not in distance selling","For deals outside the business premises and distance selling","Only for deals between two companies (B2B)","For all purchase contracts without exception, even in a shop"],explanation:"Special rights of withdrawal apply to deals outside the seller's business premises (e.g. doorstep sales) and to distance selling (e.g. online shop).",correctIndex:1},{question:"A customer orders chocolates in Loopy's online shop but wants to cancel the order. Does she have to give a reason or pay a fee?",options:["Yes, she must give a good reason and pay a fee","No, neither a reason nor a fee is necessary","Only a fee is necessary","Only a reason is necessary"],explanation:"With the special right of withdrawal in distance selling, the buyer can withdraw without giving reasons and without paying a cancellation fee.",correctIndex:1},{question:"How long is the regular withdrawal period for an online purchase if Loopy has properly informed her customers about the right of withdrawal?",options:["7 calendar days","14 calendar days","30 calendar days","6 months"],explanation:"If the buyer was properly informed, the regular withdrawal period for distance contracts is 14 calendar days.",correctIndex:1},{question:"What happens to the withdrawal period if Loopy does NOT inform her online customers about the right of withdrawal?",options:["The period is extended to exactly 6 months from delivery of the goods","The period is extended to up to 12 months and 14 calendar days","There is then no statutory right of withdrawal at all","The period stays unchanged at 14 calendar days from delivery"],explanation:"If the seller does not properly inform about the right of withdrawal, the withdrawal period is extended to up to 12 months and 14 calendar days.",correctIndex:1},{question:"When does the 14-day withdrawal period usually start for goods ordered in an online shop?",options:["From the day the contract is concluded","From the day the goods are delivered","From the day the invoice is issued","From the first working day of the month"],explanation:"For goods ordered, the withdrawal period usually starts on the day the goods are delivered.",correctIndex:1}],"bestandteile-kaufvertrag":[{question:"Which three elements are among the statutory minimum elements of a purchase contract?",options:["Contracting parties, quality, quantity","Price, delivery terms, payment terms","Guarantee, packaging, retention of title","Terms and conditions, discount, cash discount"],explanation:"Contracting parties (buyer and seller), quality and quantity are the statutory minimum elements – without them no valid purchase contract is formed.",correctIndex:0},{question:'Loopy agrees with a cocoa supplier that the beans must be delivered "according to the sample provided". Which form of specifying quality is this?',options:["Description","Sample","Standards/quality seals","Inspection"],explanation:"With a purchase by sample, the seller provides a reference item, and the goods delivered must match its condition exactly.",correctIndex:1},{question:'Which form of stating quantity applies if "approximately 500 kg" is agreed in the purchase contract?',options:["Contract with exact quantity","Contract with approximate quantity","Contract without quantity (in bulk)","Contract with open quantity"],explanation:'Additions such as "approximately" or "about" indicate an approximate quantity; a deviation of about +/-5% is usual here.',correctIndex:1},{question:`Loopy's Candy Store buys a whole lot of "leftover chocolate" from a wholesaler "in bulk" (in Bausch und Bogen). What does that mean?`,options:["The quantity is weighed exactly before handover and recorded in the contract","Only an approximate quantity with tolerance is agreed","The entire available quantity is bought without an exact quantity","Loopy can still change the purchased quantity after delivery"],explanation:'With a purchase "in bulk", the entire available quantity (e.g. a whole warehouse) is sold without an exact quantity.',correctIndex:2},{question:"What is the price called that is freely formed by supply and demand on the stock exchange or a market?",options:["Competitive price","Cost-based price","Market or exchange price","Price fixed by the authorities"],explanation:"The market or exchange price is created by the free interaction of supply and demand.",correctIndex:2},{question:"A competitor of Loopy lowers the prices for chocolates. Loopy adjusts her own prices accordingly to stay competitive. Which pricing method is Loopy using?",options:["Cost-based pricing with a profit mark-up","Competition-based pricing","Market pricing on the exchange","Discount in kind"],explanation:"With competition-based pricing, the company bases its prices on those of its competitors.",correctIndex:1},{question:"Loopy gives a regular customer who buys 100 kg of chocolates two extra kilograms free of charge. Which form of discount is this?",options:["Quantity discount","Discount in kind","Market launch discount","Cash discount"],explanation:"With a discount in kind, the buyer receives extra goods instead of a price reduction in money.",correctIndex:1},{question:'What is meant by "cash discount" (Skonto)?',options:["A price reduction for particularly large purchase quantities","A price reduction for payment within a short period","A discount for regular customers with a long business relationship","A contractual penalty paid by the seller for late delivery"],explanation:"A cash discount is a price reduction the buyer gets if he pays within a short period (e.g. 8 days).",correctIndex:1},{question:'Loopy orders chocolate boxes "ex works". What does this delivery term mean?',options:["The seller bears costs and risk up to the buyer's home","The buyer collects the goods from the seller and bears costs and risk from there","The seller delivers the goods free of charge to the buyer's front door","Costs and risk pass to the buyer at different points in time"],explanation:`"Ex works" means that the buyer collects the goods from the seller and bears costs and risk from the handover at the seller's premises.`,correctIndex:1},{question:"What is the purpose of a retention of title in a purchase contract?",options:["The seller remains the owner until full payment and thus protects himself","The seller gives up his ownership of the goods in favour of the buyer","The buyer immediately receives full ownership, regardless of payment","It only regulates the packaging and transport of the goods to the buyer"],explanation:"With a retention of title, the seller remains the owner of the goods until full payment and thus protects himself.",correctIndex:0}],"schriftverkehr-kaufvertrag":[{question:"In which order do the phases of a purchase contract usually take place?",options:["Fulfilment – conclusion – initiation","Initiation – conclusion – fulfilment","Conclusion – initiation – fulfilment","Fulfilment – initiation – conclusion"],explanation:"A purchase contract goes through the phases of initiation, conclusion and fulfilment.",correctIndex:1},{question:"A customer sends Loopy an enquiry without naming specific quantities or a delivery date, just asking in general for a catalogue. What type of enquiry is this?",options:["Specific enquiry","General enquiry","Binding offer","Order"],explanation:"With a general enquiry, the interested party only wants basic information such as catalogues or price lists.",correctIndex:1},{question:'What is a characteristic of a "solicited offer"?',options:["It is sent by the seller without an enquiry","It is created in response to the buyer's enquiry","It is never legally binding for the seller","It contains no prices"],explanation:"A solicited offer is created after a customer has made an enquiry.",correctIndex:1},{question:"Loopy receives offers for cocoa beans from two suppliers and compares price, delivery time and payment terms. What is Loopy doing here?",options:["An enquiry to the suppliers","A comparison of offers","An order","An order confirmation"],explanation:"When comparing offers, several offers are compared in terms of price, delivery and other conditions in order to choose the best one.",correctIndex:1},{question:"Loopy orders exactly the goods, quantity and terms that were in the seller's offer. Does the seller have to issue an order confirmation?",options:["Yes, within three working days of receiving the order","No, the matching order has already concluded the contract","Only if the buyer explicitly asks for it when ordering","Yes, because no contract is valid without an order confirmation"],explanation:"If the order matches the previous offer exactly, the contract is already concluded; an order confirmation is then not strictly necessary.",correctIndex:1},{question:"A customer orders a different quantity from Loopy than in the original offer. What must the seller do now for a valid contract to be formed?",options:["Nothing, the contract applies automatically on the terms of the offer","Issue an order confirmation, which the buyer must accept","Ignore the order and wait for a new order","Deliver immediately"],explanation:"If the order differs from the offer, the seller must issue an order confirmation, which counts as a new offer and must be accepted by the buyer.",correctIndex:1},{question:"Which document accompanies the goods on delivery and serves as proof of the type and quantity of products delivered?",options:["Invoice","Delivery note","Enquiry","Order confirmation"],explanation:"The delivery note accompanies the delivery and lists the items delivered.",correctIndex:1},{question:"Which detail must a proper invoice contain according to the VAT Act (UStG)?",options:["The name of the responsible sales representative","The VAT ID number of the supplying company","The signature of the managing director","The buyer's social security number"],explanation:"The statutory elements of an invoice include e.g. name and address of both parties, quantity, price, tax rate, date of issue, invoice number and the VAT ID number.",correctIndex:1},{question:"What should sensibly happen first when a delivery arrives at Loopy's?",options:["Pay the invoice immediately","Accept and check or sort the products","Immediately file a complaint with the supplier","Arrange payment without checking the goods"],explanation:"First the delivered products are accepted and checked/sorted, then the invoice is compared with the order and delivery note, and finally it is paid on time.",correctIndex:1},{question:"By when should an invoice usually be paid if no cash discount is taken?",options:["Immediately on receipt, regardless of the date","Within the agreed payment period","Only one year after the invoice date","Never, invoices expire automatically"],explanation:"Invoices must be paid on time, i.e. within the agreed payment period – otherwise the buyer is in default of payment.",correctIndex:1}],"zahlungsformen-1jg":[{question:"A customer pays for his chocolates in Loopy's Candy Store directly with coins and notes at the till. What method of payment is this?",options:["Cash payment","Bank transfer","Direct debit","M-payment via app"],explanation:"With cash payment, you pay directly with cash (coins and banknotes).",correctIndex:0},{question:"Which security feature of banknotes can you see by holding the note up to the light?",options:["Emerald number with colour change","Portrait watermark","Microprint","Tactile raised print"],explanation:"The portrait watermark becomes visible when held up to the light and is an important security feature of genuine banknotes.",correctIndex:1},{question:"Loopy opens an account together with her business partner where each of them can use the account alone. What type of account is this?",options:["Joint account (both together)","Joint account (either-or)","Single account","Savings account"],explanation:"With an either-or account (joint account), each authorised person can use the account alone.",correctIndex:1},{question:"What is a payment order called that Loopy uses to have regularly recurring, constant amounts (e.g. rent) transferred automatically?",options:["Collection order","Standing order","Cash on delivery","Cash discount"],explanation:"A standing order automatically transfers constant amounts to a fixed recipient at regular intervals.",correctIndex:1},{question:"Loopy allows her electricity provider to collect the amount due from her account by itself. What is this procedure called?",options:["Standing order with a fixed amount","SEPA direct debit","Cash payment","Credit card payment"],explanation:"With SEPA direct debit, the payee collects the amount due directly from the payer's account.",correctIndex:1},{question:"What is the interest called that a bank credits to the account holder for a positive balance on the current account?",options:["Debit interest","Credit interest","Default interest","Overdraft interest"],explanation:"Credit interest is credited to the account holder for a positive balance; debit interest, on the other hand, is charged when the account is overdrawn.",correctIndex:1},{question:"What do IBAN and BIC stand for?",options:["International account number and international bank identifier code","Internal bank information and international bank identifier code","International bank payout number and bank account code","Individual bank details and bank-internal code system"],explanation:"IBAN (International Bank Account Number) is the international account number, BIC (Bank Identifier Code) clearly identifies the bank.",correctIndex:0},{question:"Loopy pays online with her card, and the amount is debited immediately from her current account. What type of card is this?",options:['Credit card ("pay later")','Debit card ("pay now")','Prepaid card ("pay before")',"Gift card"],explanation:'With a debit card the amount is debited immediately ("pay now") from the current account.',correctIndex:1},{question:"What is the procedure called in which Loopy must additionally confirm an online transfer with a code on her smartphone?",options:["TAN procedure (e.g. push TAN)","Cash discount","Cash on delivery","Direct debit procedure (collection order)"],explanation:"The TAN procedure (e.g. push TAN) provides additional security for online banking transactions.",correctIndex:0},{question:"A customer conveniently pays for his order in Loopy's online shop directly with his smartphone using a payment app. What is this method of payment called?",options:["Cash on delivery","M-payment (mobile payment)","Cash discount","Standing order via online banking"],explanation:"M-payment means paying with your smartphone, e.g. via a payment app.",correctIndex:1}],"unzuverlaessige-verkaeufer":[{question:"When is a seller in default of delivery?",options:["When he charges the buyer more than the agreed price","When he does not deliver on time or as contractually agreed","When the buyer does not collect the goods on the agreed date","When an invoice is incorrect"],explanation:"Late delivery occurs when the seller does not provide the agreed performance on time or as agreed in the contract.",correctIndex:1},{question:'For a Christmas party, Loopy orders special chocolate boxes with the fixed date "20 December at the latest". The supplier only delivers on 27 December. What type of transaction was it?',options:["Ordinary forward transaction","Fixed-date transaction","Advance payment transaction","Bulk purchase"],explanation:"With a fixed-date transaction, meeting the delivery date is essential for the deal (e.g. Christmas goods); if the date is missed, there is usually no longer any interest in the late delivery.",correctIndex:1},{question:"What must the buyer usually do first in an ordinary forward transaction before he can withdraw from the contract?",options:["Withdraw immediately without further steps","Set a reasonable extra period","Sue for damages","Accept the goods anyway"],explanation:"In an ordinary forward transaction the buyer usually has to give the seller a reasonable extra period first before he can withdraw.",correctIndex:1},{question:"What type of defect is it if a fault in the goods is immediately visible on careful inspection?",options:["Hidden defect","Obvious defect","Fraudulently concealed defect","Irreparable defect"],explanation:"An obvious defect can be seen immediately during inspection.",correctIndex:1},{question:"Only months after buying a new packaging machine does Loopy discover a manufacturing fault that could not be seen at handover. What type of defect is this?",options:["Obvious defect","Hidden defect","Minor defect","Major defect"],explanation:"A hidden defect only becomes noticeable after some time and could not be seen at handover.",correctIndex:1},{question:"How long is the statutory warranty period in Austria for new movable items (e.g. a machine)?",options:["6 months","1 year","2 years","10 years"],explanation:"For new movable items there is a statutory warranty period of 2 years from handover.",correctIndex:2},{question:"Which rights does the buyer primarily have for a defective product (primary warranty remedies)?",options:["Immediate cancellation of the contract","Improvement (repair) or replacement","Only a price reduction","Damages of any amount"],explanation:"In case of defects, the buyer is first entitled to improvement (repair) or replacement of the defective product.",correctIndex:1},{question:"How does a guarantee differ from the statutory warranty?",options:["A guarantee is mandatory by law, the warranty is voluntary","A guarantee is voluntary, the warranty is required by law","Both are identical","A guarantee only applies to digital products, the warranty to all goods"],explanation:"A guarantee is a voluntary promise (often limited in time), while the warranty is a legal obligation of the seller.",correctIndex:1},{question:"What should Loopy do if she finds a wrong quantity or wrong price on her supplier's invoice?",options:["Simply ignore the invoice","Pay the invoice immediately without asking","Complain about the errors and ask for a corrected invoice","Send back the goods without checking the invoice"],explanation:"With an incorrect invoice, the buyer should complain about the error and ask for a corrected invoice.",correctIndex:2}],"unzuverlaessige-kaeufer":[{question:"When is a buyer in default of acceptance?",options:["When he pays too early","When he does not accept the goods properly delivered","When he files a complaint with the seller about a defect","When he cancels the purchase contract before delivery"],explanation:"Default of acceptance occurs when the buyer does not accept the goods properly offered to him.",correctIndex:1},{question:"A customer orders a large quantity of chocolates from Loopy for a party but does not collect them despite several reminders. Apart from insisting on the contract, what option does Loopy have?",options:["She must give the chocolates away for free","She can withdraw from the contract or carry out a self-help sale","She may not do anything without a court ruling","She must automatically extend the contract by three months"],explanation:"With default of acceptance, the seller can withdraw from the contract or sell the goods elsewhere in a self-help sale.",correctIndex:1},{question:"When is a buyer in default of payment?",options:["When he pays the invoice before it is due","When he does not pay the purchase price on time","When he pays too much","When he collects the goods from the seller earlier than agreed"],explanation:"Default of payment occurs when the buyer does not pay the purchase price by the agreed due date.",correctIndex:1},{question:"How high is the statutory default interest for late payment between two companies (B2B) in Austria?",options:["4 percentage points above the current base rate","9.2 percentage points above the base rate","A fixed 9.2% per year, regardless of the base rate","1% per month"],explanation:"In B2B deals the statutory default interest is 9.2 percentage points above the base rate, in B2C/C2C deals it is 4%.",correctIndex:1},{question:"Which of the following options does a seller have if the buyer is in default of payment?",options:["Only a lawsuit is possible","Insist on the contract and send reminders OR withdraw from it","He must automatically cancel the contract","He may take the goods back immediately without informing the buyer"],explanation:"If the buyer is in default of payment, the seller can either insist on the contract and send the buyer reminders, or withdraw from the contract under certain conditions.",correctIndex:1},{question:"One of Loopy's customers has not yet paid his invoice. Loopy first sends him a friendly reminder. What is this first step of the dunning process called?",options:["Final reminder with threat of legal action","Payment reminder (1st reminder)","Debt collection by an agency","Lawsuit"],explanation:"The payment reminder is usually the first, friendly step in the dunning process.",correctIndex:1},{question:"What is typically the last out-of-court step in the dunning process before a company starts court payment order proceedings?",options:["The first friendly payment reminder, usually without any deadline","The final reminder with a deadline and threat of legal action","The purchase contract","The invoice itself"],explanation:"After several unsuccessful reminder stages, a final reminder usually follows before legal action (e.g. court payment order proceedings) is taken.",correctIndex:1},{question:"What is a payment order in court payment order proceedings?",options:["A voluntary request for payment from the creditor without legal effect","A court order to the debtor to pay the amount or to object","A written reminder from the creditor threatening legal action","A till receipt"],explanation:"The payment order is a court order requiring the debtor to pay the outstanding amount or to object within the deadline.",correctIndex:1},{question:"What happens if the debtor does not object to the payment order within the deadline?",options:["The payment order becomes invalid","The payment order becomes final and enforceable","The creditor must send reminders again","The case is closed without payment"],explanation:"If the debtor does not object, the payment order becomes final and enforceable.",correctIndex:1}],rechtsdurchsetzung:[{question:"What should be the first step if a contracting partner has breached his duties?",options:["File a lawsuit at the competent court immediately","Clarify what you actually want to achieve","Break off contact with the partner immediately","Send the goods back immediately without any discussion"],explanation:"First you should clarify your own interests: What do you actually want to achieve?",correctIndex:1},{question:"Loopy has a dispute with a supplier about a defective delivery. Before going to court, she seeks a clarifying conversation with the supplier. What is this first step called?",options:["Lawsuit at the district court","Notifying the contracting partner","Enforcement by the competent court","Court dunning procedure"],explanation:"An important early step is notifying or talking to the contracting partner to settle the matter.",correctIndex:1},{question:"What is typically a disadvantage of a legal dispute in court?",options:["It is usually very quick and free of charge","It can cause high costs and take a long time","It always guarantees victory","It requires no evidence"],explanation:"Legal disputes in court can be expensive (e.g. court and lawyer's fees) and take a long time.",correctIndex:1},{question:"Who generally bears the burden of proof for a disputed claim in civil proceedings?",options:["Always the defendant, regardless of the claim","The person who relies on the claim","Always the court","Nobody, the court decides without evidence"],explanation:"In principle, whoever makes a claim must also prove it (burden of proof).",correctIndex:1},{question:"Instead of suing, Loopy agrees on a price reduction with an unhappy customer in a personal conversation as a goodwill gesture. What is this form of out-of-court dispute resolution called?",options:["Mediation","Goodwill","Arbitration tribunal","Lawsuit"],explanation:"Goodwill means that a company voluntarily accommodates the customer without being legally obliged to.",correctIndex:1},{question:"What is mediation?",options:["A binding judgement given by a judge after the hearing","A procedure where a neutral mediator helps the parties agree","A payment order","A form of enforcement carried out by a bailiff"],explanation:"In mediation, a neutral mediator supports the parties in finding an agreed solution themselves.",correctIndex:1},{question:"What is the difference between a conciliation body and an arbitration tribunal?",options:["A conciliation body makes binding decisions, an arbitration tribunal only non-binding recommendations","A conciliation body makes non-binding recommendations, an arbitration tribunal binding decisions","Only the arbitration tribunal is free of charge","A conciliation body can only be called on for B2B deals"],explanation:"Conciliation bodies usually give non-binding recommendations, while an arbitration tribunal makes a binding decision like a private court.",correctIndex:1},{question:"Which alternatives to a court case should be considered before suing?",options:["Immediate enforcement against the partner without a court judgement","Goodwill, mediation, conciliation body or arbitration tribunal","Calling the police straight away and pressing charges","Simply forgetting about it"],explanation:"Before an expensive and lengthy court case, alternatives such as goodwill, mediation, a conciliation body or an arbitration tribunal should be considered.",correctIndex:1}],"unternehmensgruendung-schritte":[{question:"What is an advantage of self-employment compared to being employed?",options:["A fixed, secure salary even in weak months","Free choice of hours and your own decisions","No personal entrepreneurial risk","No financial outlay needed for the start-up"],explanation:"Self-employed people can organise their time freely and make decisions independently – but they also bear the entrepreneurial risk.",correctIndex:1},{question:"Before Loopy founded her own Candy Store, she considered whether to take over an existing shop, open a franchise or start from scratch. What did she do here?",options:["Applied for a trade licence","Weighed up different ways to her own business idea","Checked the requirements for a trade licence","Concluded a purchase contract for a shop"],explanation:"There are different ways to your own business idea: a new start-up, taking over an existing company, or franchising.",correctIndex:1},{question:'What is meant by "franchising"?',options:["Completely reinventing a business model","Using a proven business concept from a franchisor for a fee","Taking over a company from your own parents","State funding for start-ups with an innovative idea"],explanation:"With franchising, the franchisee uses a franchisor's tested business concept for a fee.",correctIndex:1},{question:"Which requirement must a natural person at least meet in order to register a trade in Austria?",options:["Be at least 25 years old and have a residence in Austria","Be of age and be generally reliable","Have a university degree or the Matura","Already have owned a company"],explanation:"The general requirements for a trade licence include being of age (18), EU/EEA citizenship (or equivalent) and no grounds for exclusion.",correctIndex:1},{question:"To run Loopy's Candy Store as a pastry shop, Loopy needs proof of her professional qualification. What is this proof called?",options:["Reliability check","Certificate of competence","Trade licence document","Extract from the company register"],explanation:"The certificate of competence proves the professional and commercial qualification for a regulated trade.",correctIndex:1},{question:"How does a free trade differ from a regulated trade?",options:["Free trades additionally require a certificate of competence, regulated trades do not","Regulated trades additionally require a certificate of competence, free ones do not","There is no difference","Free trades may only be run by foreigners"],explanation:"Regulated trades (e.g. baker, electrician) additionally require a certificate of competence; for free trades the general trade licence is enough.",correctIndex:1},{question:"What is the purpose of checking a business idea before starting a company?",options:["To check customer benefit, feasibility and economic viability","To prepare the first tax return for the tax office","To get a loan from the bank immediately and without any collateral","To inform the competition about your plans in good time"],explanation:"The check examines whether the business idea offers customer benefit, is feasible, economical and suitable for the founder.",correctIndex:0},{question:"What is typically not an advantage but a disadvantage of self-employment?",options:["Free choice of working hours","Self-fulfilment","Higher financial risk and irregular income","Being able to make your own decisions without consulting a boss"],explanation:"A disadvantage of self-employment is the higher financial risk and often irregular income, especially in the early phase.",correctIndex:2},{question:"What happens in a business takeover, as opposed to a new start-up?",options:["A completely new company is built from scratch","An existing company is continued by a successor","The sole proprietorship automatically becomes a corporation","It is prohibited by law"],explanation:"In a business takeover, an existing company (e.g. from a family member) is taken over and continued by a successor.",correctIndex:1}],"wahl-der-rechtsform-1jg":[{question:"Which criterion does not directly influence the choice of a company's legal form?",options:["The number of owners and partners","Liability","Raising capital","The favourite colour of the company logo"],explanation:"Criteria for choosing the legal form include the number of owners, raising capital, liability, management and share in profit – but not design details like a logo colour.",correctIndex:3},{question:"Loopy starts her Candy Store all alone, without partners, and is liable with all her private assets. Which legal form has Loopy chosen?",options:["GmbH","Sole proprietorship","Public limited company","General partnership"],explanation:"In a sole proprietorship there is only one owner, who is liable without limit with all of their assets.",correctIndex:1},{question:"What is a disadvantage of a sole proprietorship?",options:["Quick and easy set-up without a partnership agreement","Unlimited liability with private assets","No minimum capital needed","The profit does not have to be shared with anyone"],explanation:"A key disadvantage is the sole proprietor's unlimited liability with all of their private assets.",correctIndex:1},{question:"Which group of legal forms does the GmbH (private limited company) belong to?",options:["Sole proprietorship","Partnership","Corporation","Association"],explanation:"The GmbH is a corporation in which the shareholders are generally only liable with their capital contribution.",correctIndex:2},{question:"Which of the following legal forms is a partnership?",options:["General partnership (OG)","Public limited company (AG)","Private limited company (GmbH)","Association"],explanation:"The OG (like the KG) is a partnership; the AG and GmbH, on the other hand, are corporations.",correctIndex:0},{question:"Which criterion describes who makes the decisions in the company and exercises control?",options:["Raising capital","Management and control","Share in profit of the partners","Number of owners/partners"],explanation:"Management and control determine who decides in the company and who runs the business.",correctIndex:1},{question:"Loopy is considering whether to start her Candy Store with a friend where both are fully personally liable, or to set up a corporation where only the company's assets are liable. Which criterion is most important here?",options:["Raising capital","Liability","Share in profit","Type of bookkeeping"],explanation:"This is about the criterion of liability – in partnerships the partners are usually personally liable, in corporations generally only the company's assets are.",correctIndex:1},{question:'What is meant by "share in profit" as a criterion when choosing the legal form?',options:["What the company is called","How profit and loss are shared out among the owners","Which taxes are payable on the company's profit","How many employees may be employed at most"],explanation:"The share in profit regulates how the company's profit and loss are divided among the owners/partners.",correctIndex:1}],"businessplan-1jg":[{question:"What is a business plan?",options:["An advertising brochure informing customers about the range","A written plan of the business idea and how it will be implemented","A tax form required by law for newly founded companies","A price list of all products and services"],explanation:"The business plan is a written concept that describes the business idea, the market and its implementation in detail.",correctIndex:1},{question:"Before Loopy starts her Candy Store, she writes a business plan to check whether her idea is feasible and can be economically successful, and to convince potential investors. Which function does the business plan mainly fulfil here?",options:["Assessing and convincing (financing partners)","Steering operations after the opening","Only advertising to future customers","Replacing the ongoing bookkeeping"],explanation:"The business plan is used, among other things, to assess the business idea (feasible? economical?) and to convince financing partners such as banks of the idea.",correctIndex:0},{question:"Which of the following is not a typical component of a business plan?",options:["Business idea and target group","Marketing concept","Financial planning and capital requirements","The founder's favourite film"],explanation:"A business plan includes the business idea, market/target group, marketing, location, opportunities/risks and financial planning – personal details unrelated to the business do not belong in it.",correctIndex:3},{question:"Why is analysing the competition and the market an important part of the business plan?",options:["To copy the products and prices of the competition","To assess your own idea realistically and recognise opportunities/risks","Because it is required by law, even though it has no benefit","To raise your own prices as you like, regardless of the market and competitors"],explanation:"Market and competitor analysis helps to assess your own business idea realistically and to recognise opportunities and risks early on.",correctIndex:1},{question:"In the financial plan of her business plan, Loopy calculates how much money she needs at the start for rent, machines and buying goods. What is this figure called?",options:["Capital requirement","Cash discount","Contribution margin","Turnover discount"],explanation:"The capital requirement indicates how much start-up capital a company needs for founding and the first few months.",correctIndex:0},{question:"What function does the business plan have while the company is running?",options:["Only for presenting once to the bank at the start","As a steering tool to check goals and adjust the course","It is no longer needed after the start and is filed away","It then serves only as advertising material for customers"],explanation:"The business plan also serves as a steering tool after founding, with which the founder can compare actual development with the planned goals.",correctIndex:1},{question:'What is meant by the "customer benefit" that a business plan should work out?',options:["The profit the company makes from each customer","The concrete advantage the offer brings to the customer","The number of employees who look after customers","The legal form under which the company deals with customers"],explanation:"The customer benefit describes which concrete advantage or need the offer fulfils for customers.",correctIndex:1},{question:"Why should the business plan also address possible risks of the project?",options:["To scare investors off from taking part","To deal realistically with challenges and prepare solutions","Because it is required by law, even though it has no practical use","Risks are never mentioned in a business plan, only opportunities"],explanation:"Dealing with opportunities and risks shows that the founder has looked realistically at possible challenges.",correctIndex:1}],"vertraege-mitarbeiter":[{question:'What characterises a "genuine" employment contract?',options:["The employee is completely independent in time and place","Personal and economic dependence on the employer","Only a specific result is owed, not any working time","The employer has no right to give instructions"],explanation:"In a genuine employment contract, the employee is personally and economically dependent on the employer and integrated into their business.",correctIndex:1},{question:"Loopy hires a graphic designer who designs a new logo for Loopy's Candy Store from home, with her own equipment and flexible hours, without being firmly integrated into the business. Which type of contract is this most likely to be?",options:["Genuine employment contract","Freelance service contract","Apprenticeship contract","The industry's collective agreement"],explanation:"With a freelance service contract, the person is largely independent, largely decides working hours and place themselves and bears a certain entrepreneurial risk.",correctIndex:1},{question:"How does a contract for work fundamentally differ from an employment contract?",options:["A specific result (work) is owed and no employment relationship is created","There is no payment at all for a contract for work, only expenses","A contract for work can only be concluded orally; a written form is not allowed","There is no difference, both create an employment relationship"],explanation:"With a contract for work, the contractor undertakes to produce a specific piece of work (result), and no employment relationship is created.",correctIndex:0},{question:"What is a statement of employment terms (Dienstzettel)?",options:["A binding, independent contract that replaces the employment contract","A written summary of the key points of an existing employment relationship","A written letter of notice from the employer to the employee","A monthly payslip showing the deductions for tax and social security"],explanation:"The statement of employment terms summarises the key points of the existing employment relationship in writing (e.g. start, pay, activity), but is not a contract in itself.",correctIndex:1},{question:"Loopy hires a new sales assistant for her Candy Store. Does a written employment contract have to be concluded for the employment to be valid?",options:["Yes, without a written contract the employment is invalid from the start","No, it has no set form; an oral agreement or implied conduct is enough","Only for full-time jobs is the written form compulsory","Only for employees who are minors is writing compulsory"],explanation:"The employment contract has no set form; it can be concluded orally, in writing or even by implied conduct (e.g. starting work).",correctIndex:1},{question:"When does an employment relationship usually begin?",options:["Only with the first salary payment","With the actual start of work","Only after the probationary period","Only when the statement of employment terms is issued"],explanation:"The employment relationship generally begins with the actual start of work, i.e. when work actually begins.",correctIndex:1},{question:"Which form of employment typically involves the highest entrepreneurial risk for the worker?",options:["Genuine employment contract (employee)","Contract for work (self-employed)","Apprenticeship contract","There is no difference in risk"],explanation:"With a contract for work, the contractor, as a self-employed person, bears the full entrepreneurial risk for producing the agreed work.",correctIndex:1},{question:"Does an employer have to issue a statement of employment terms for a genuine employment relationship?",options:["No, it is never necessary for a genuine employment relationship","Yes, unless there is a written contract with the essential content","Only for part-time work, not for full-time employment","Only if the employee is a minor or an apprentice"],explanation:"If there is no written employment contract with the essential content, the employer must immediately issue a statement of employment terms with the key details.",correctIndex:1}]}};export{e as default};
